(()=>{'use strict';
const B=Business,KEY='note-work-org-demo-v1',pages=[['index','Bắt đầu'],['cau-hinh','Tiêu chí và mẫu chỉ tiêu'],['chi-tieu','Chỉ tiêu năm'],['bao-cao','Báo cáo kết quả'],['tu-danh-gia','Tự đánh giá'],['tham-dinh','Thẩm định và công nhận'],['ket-qua','Kết quả và in']];
let s;try{s=JSON.parse(localStorage.getItem(KEY));if(s?.schema!==1)s=null;}catch{}s=s||B.seed();let page=document.body.dataset.page,tab='main',tourIndex=0,tourSteps=[],dialogDirty=false;
const $=q=>document.querySelector(q),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=v=>v===null||v===undefined?'—':Number(v).toLocaleString('vi-VN',{minimumFractionDigits:2,maximumFractionDigits:2}),date=v=>v?new Date(v+'T00:00:00').toLocaleDateString('vi-VN'):'—';
const roles={unit:'Người lập của đơn vị',admin:'Người cấu hình / duyệt kế hoạch',verifier:'Người xác nhận số liệu',head:'Người đứng đầu đơn vị',reviewer:'Người thẩm định',approver:'Người công nhận',viewer:'Chỉ xem'},rating={excellent:'Hoàn thành xuất sắc',good:'Hoàn thành tốt',pass:'Hoàn thành',fail:'Không hoàn thành'},status={draft:'Nháp',pending:'Chờ duyệt',approved:'Đã duyệt',returned:'Cần bổ sung',confirmed:'Đã xác nhận',waiting:'Chờ xác nhận',head:'Chờ người đứng đầu',submitted:'Đã trình thẩm định',reviewed:'Đã thẩm định',recognized:'Đã công nhận',configuring:'Chờ cấu hình'};
function save(action){if(action)s.log.unshift({at:new Date().toLocaleString('vi-VN'),role:roles[s.role],action,planVersion:s.plan.version});try{localStorage.setItem(KEY,JSON.stringify(s));}catch{toast('Trình duyệt không lưu được dữ liệu. Hãy cho phép lưu dữ liệu trang web.');}}
function toast(t){$('.toast')?.remove();const x=document.createElement('div');x.className='toast';x.setAttribute('role','status');x.textContent=t;document.body.append(x);setTimeout(()=>x.remove(),5500);}
function allowed(...r){return r.includes(s.role);}function guard(...r){if(!allowed(...r)){toast('Thao tác này dành cho: '+r.map(x=>roles[x]).join(', ')+'. Chọn vai trò tương ứng ở đầu trang để thử.');return false;}return true;}
const badge=x=>`<span class="badge ${['approved','confirmed','recognized'].includes(x)?'ok':['returned'].includes(x)?'bad':'wait'}">${esc(status[x]||x)}</span>`,btn=(text,act,extra='',kind='')=>`<button class="${kind}" data-action="${act}" ${extra}>${text}</button>`,source=t=>`<span class="source">${t}</span>`;
let fieldSeq=0;
function field(label,id,v='',type='text',help='',attrs=''){id=id||'field-'+(++fieldSeq);return `<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" value="${esc(v)}" ${type==='number'?'step="any"':''} ${attrs}>${help?`<small>${help}</small>`:''}</div>`;}
function select(label,id,opts,v,help=''){return `<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${id}">${Object.entries(opts).map(([k,n])=>`<option value="${k}" ${String(v)===k?'selected':''}>${n}</option>`).join('')}</select>${help?`<small>${help}</small>`:''}</div>`;}
function textfield(label,id,v,help=''){return `<div class="field full"><label for="${id}">${label}</label><textarea id="${id}" name="${id}">${esc(v)}</textarea><small>${help}</small></div>`;}
function check(label,id,v){id=id||'field-'+(++fieldSeq);return `<div class="field"><label><input id="${id}" name="${id}" type="checkbox" ${v?'checked':''}>${label}</label></div>`;}
function optsRating(id,v){return select('Mức đề xuất (điểm và điều kiện phải cùng phù hợp)',id,rating,v);}
function table(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">Chưa có dữ liệu. Thực hiện bước được hướng dẫn phía trên.</td></tr>`}</tbody></table></div>`;}
function title(k,text,desc,actions=''){return `<div class="pagehead"><div><div class="eyebrow">Đánh giá tổ chức · Bước ${k}/6</div><h1>${text}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
function guide(text){return `<div class="guidebar"><div><span class="marker">HƯỚNG DẪN</span><b>Làm đúng từng bước</b><p>${text}</p></div><div class="actions">${btn('Bắt đầu hướng dẫn','tour','id="guide-start"','primary')}</div></div>`;}
function tabs(items){return `<div class="tabs">${items.map(([k,t])=>`<button data-action="tab" data-tab="${k}" class="${tab===k?'active':''}">${t}</button>`).join('')}</div>`;}
function statebar(){return `<div class="path">${['draft','head','submitted','reviewed','recognized'].map(x=>`<span class="${s.assessment.status===x?'current':''}">${{draft:'Tự đánh giá',head:'Người đứng đầu xác nhận',submitted:'Thẩm định',reviewed:'Công nhận',recognized:'Thông báo'}[x]}</span>`).join('')}</div>`;}
function render(){stopTour();const content=({index:home,'cau-hinh':config,'chi-tieu':plan,'bao-cao':reports,'tu-danh-gia':assessment,'tham-dinh':review,'ket-qua':results}[page])();$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><b>N</b>NOTE WORK</div><small>Đánh giá tổ chức</small><nav class="nav">${pages.map(([k,t],i)=>`<a href="${k}.html" class="${page===k?'active':''}" ${page===k?'aria-current="page"':''}><span class="num">${i||'↗'}</span>${t}</a>`).join('')}</nav><div class="sidebottom">Môi trường trình diễn<br>Dữ liệu ví dụ lưu trên trình duyệt.<br><a style="color:#d9e9df" href="nghiep-vu.html">Giải thích nghiệp vụ →</a></div></aside><div><header class="topbar"><div class="context"><b>${esc(s.org)}</b><span class="badge">Năm ${s.year}</span><span class="muted">Cấp quản lý mẫu</span></div><div class="context"><label style="margin:0" for="role">Vai trò demo</label><select id="role">${Object.entries(roles).map(([k,t])=>`<option value="${k}" ${s.role===k?'selected':''}>${t}</option>`).join('')}</select>${btn('Hướng dẫn','tour')}</div></header><main class="main" id="main">${content}<footer class="footer">NOTE WORK · Đánh giá tổ chức · Dữ liệu minh họa · <a href="nghiep-vu.html">Trường dữ liệu và quy tắc xử lý</a></footer></main></div></div>`;if(!allowed('unit')||s.assessment.status!=='draft')document.querySelectorAll('#self-notes input,#self-notes select,#self-notes textarea').forEach(x=>x.disabled=true);if(!allowed('reviewer')||s.assessment.status!=='submitted')document.querySelectorAll('#review-opinion,#review-rating').forEach(x=>x.disabled=true);}
function home(){return `<div class="pagehead"><div><div class="eyebrow">Một luồng rõ ràng từ cấu hình đến kết quả</div><h1>Đánh giá tổ chức, từng bước</h1><p>Chọn một bước để xem, hoặc đi từ đầu để hiểu dữ liệu được tạo ở đâu và ai xử lý tiếp.</p></div></div><div class="guidebar"><div><span class="marker">DEMO CÓ TƯƠNG TÁC</span><b>Từ mục tiêu đến kết quả được công nhận</b><p>Thay đổi số liệu, thử tính điểm và chuyển vai trò để trải nghiệm quy trình.</p></div><a href="cau-hinh.html"><button class="primary">Bắt đầu từ bước 1 →</button></a></div><div class="stepgrid">${pages.slice(1).map(([k,t],i)=>`<a class="stepcard" href="${k}.html"><div class="big">0${i+1}</div><h2>${t}</h2><p>${['Chuẩn bị cách đo, cách chấm và giới hạn điểm.','Gắn mẫu vào mục tiêu của đơn vị, phân bổ đủ 100 điểm.','Nhập số thực tế và gửi người có quyền xác nhận.','Tổng hợp điểm, kiểm tra điều kiện và trình hồ sơ.','Chấm riêng, xem hạn mức và quyết định kết quả.','Xem bản chính thức, xuất bảng và in phiếu.'][i]}</p><span>Mở bước ${i+1} →</span></a>`).join('')}</div><div class="card"><h2>Chọn cách trình diễn</h2><p>Bộ mẫu có 11 tiêu chí và tổng 100 điểm. Điểm của từng tiêu chí trong demo là cấu hình ví dụ, phải được người có quyền duyệt khi triển khai.</p><div class="actions">${btn('Nạp hồ sơ ví dụ đã xác nhận','scenario','id="scenario"','primary')}${btn('Làm lại từ đầu','reset','','danger')}<a href="nghiep-vu.html">Đọc nghiệp vụ và cách triển khai</a></div><p class="muted">Nạp ví dụ tạo kế hoạch đã duyệt và số liệu đã xác nhận để bắt đầu từ bước tự đánh giá. Làm lại chỉ xóa dữ liệu demo trên trình duyệt này.</p></div>`;}
function config(){const c=s.config;return title(1,'Tiêu chí và mẫu chỉ tiêu','Người cấu hình chuẩn bị quy tắc. Đơn vị sử dụng mẫu đã duyệt, không cần tự viết công thức.',btn('Chỉnh kỳ đánh giá','edit-period','id="period-button"')+btn('Thêm chỉ tiêu chuẩn','template-add','id="template-add"','primary'))+guide('Kỳ đánh giá → khung điểm → mẫu đo và chấm → kiểm tra → duyệt. Mẫu đã dùng được giữ theo phiên bản.')+`<div class="grid three"><div class="card" id="period"><span class="eyebrow">Kỳ đánh giá</span><h2 style="margin-top:8px">Năm ${s.year}</h2><p>Hạn chốt: <b>${date(c.deadline)}</b></p><p>Áp dụng từ: ${date(c.effective)}</p>${badge(c.status)} ${c.status==='draft'?btn('Trình cấu hình','config-submit'):c.status==='pending'?btn('Duyệt cấu hình','config-approve'):''} ${source('Năm/hạn/ngày áp dụng: người cấu hình nhập. Phiên bản: hệ thống tạo.')}</div><div class="card"><span class="eyebrow">Khung điểm</span><div class="stat">30 + 70 = 100</div><p>Nhóm A: cách tổ chức làm việc.<br>Nhóm B: kết quả thực hiện nhiệm vụ.</p>${source('Tổng điểm lấy khung đã duyệt; không phải kinh phí.')}</div><div class="card"><span class="eyebrow">Cấu hình đang dùng</span><div class="stat">v${c.version}</div><p>${esc(c.basis)}</p>${btn('Sao chép sang năm mới','new-year')}${source('Năm mới tạo bản nháp; hồ sơ năm cũ giữ riêng.')}</div></div>`+tabs([['main','Chỉ tiêu chuẩn'],['criteria','Khung 11 tiêu chí'],['history','Lịch sử']])+(tab==='criteria'?`<div class="card" id="criteria">${table(['Mã','Tiêu chí (tên dễ hiểu)','Điểm tối đa (điểm)'],s.criteria.map(c=>[c.code,c.title,fmt(c.cap)]))}<p class="muted">A1–A3: 30 điểm; B1–B8: 70 điểm. Demo dùng phân bổ 10/10/10 và 10/10/10/10/10/10/5/5 để minh họa.</p></div>`:tab==='history'?history():`<div class="card" id="templates"><div class="actions"><input id="search" placeholder="Tìm tên hoặc mã mẫu" aria-label="Tìm mẫu" style="max-width:340px"></div>${table(['Mẫu / tiêu chí','Cách đo / cách chấm','Nguồn số liệu','Phiên bản / trạng thái','Thao tác'],s.templates.map(t=>[`${esc(t.name)}<small>${t.id} · ${t.criterion}</small>`,`${measureName(t.measure)}<small>${scoreName(t.scoring)}</small>`,esc(t.source),`v${t.version} ${badge(t.status)}`,btn('Xem / sửa','template-edit',`data-id="${t.id}" data-version="${t.version}"`)+(t.status==='draft'?btn('Trình duyệt','template-submit',`data-id="${t.id}" data-version="${t.version}"`):t.status==='pending'?btn('Duyệt','template-approve',`data-id="${t.id}" data-version="${t.version}"`)+btn('Trả bổ sung','template-return',`data-id="${t.id}" data-version="${t.version}"`):'')]))}</div>`);}
const measureName=k=>({direct:'Giá trị trực tiếp',ratio:'Số đạt / tổng số',level:'Mức mô tả'}[k]),scoreName=k=>({completion:'Theo mức hoàn thành',range:'Theo khoảng kết quả',level:'Theo mức mô tả'}[k]);
function effectivePlan(){return s.plan.adjustment||s.plan;}
function plan(){let p=effectivePlan();const errors=B.planErrors(s,p);return title(2,'Chỉ tiêu năm','Mỗi dòng là một mục tiêu của đơn vị, kế thừa cách đo và cách chấm từ mẫu.',btn('Đề xuất chỉ tiêu mới','new-proposal')+btn(s.role==='admin'?'Giao chỉ tiêu':'Đăng ký từ mẫu','item-add','id="item-add"')+btn('Áp dụng bộ mẫu','apply-set','id="apply-set"','primary'))+guide('Áp dụng mẫu → nhập mục tiêu/hạn → phân bổ điểm → trình bảng → chuyển vai trò để duyệt. Chỉ bản đã duyệt mới được báo cáo.')+`<div class="card"><div class="actions">${badge(p.status)}<b>Kế hoạch v${p.version}</b>${p!==s.plan?'<span class="badge wait">Bản điều chỉnh · bản cũ vẫn có hiệu lực</span>':''}${btn('Nhập bảng CSV (từ Excel)','import','id="import"')}${btn('Xuất bảng chỉ tiêu','export-plan')}${s.plan.status==='approved'&&!s.plan.adjustment?btn('Đề nghị điều chỉnh','adjust-plan','id="adjust"'):''}</div></div>`+((s.proposals||[]).length?`<div class="card"><h2>Đề xuất mới chưa có mẫu</h2>${table(['Tên đề xuất','Nội dung','Trạng thái'],s.proposals.map(x=>[esc(x.name),esc(x.description),badge(x.status)]))}</div>`:'')+tabs([['main','Danh sách chỉ tiêu'],['allocation','Phân bổ điểm'],['tasks','Nhiệm vụ làm căn cứ'],['history','Lịch sử']])+(tab==='tasks'?taskView():tab==='history'?history():tab==='allocation'?`<div class="card" id="allocation"><h2>Phân bổ điểm (điểm, không phải tiền)</h2>${table(['Tiêu chí','Điểm tối đa','Tổng đã phân bổ','Đối chiếu'],s.criteria.map(c=>{const n=p.items.filter(i=>i.criterion===c.code).reduce((n,i)=>n+i.cap,0);return [c.code+' · '+c.title,fmt(c.cap),fmt(n),`<span class="badge ${n===c.cap?'ok':'bad'}">${n===c.cap?'Đủ':n<c.cap?'Thiếu':'Vượt'}</span>`];}))}${btn('Sửa phân bổ','allocation','id="allocation-edit"','primary')}<p class="muted">Người cấu hình sửa điểm từng chỉ tiêu. Chia đều chỉ là gợi ý; tổng điểm con phải bằng điểm tiêu chí.</p></div>`:`<div class="card" id="plan-table"><input id="search" placeholder="Tìm tên hoặc mã chỉ tiêu" aria-label="Tìm chỉ tiêu" style="max-width:350px;margin-bottom:15px">${table(['Tên / tiêu chí','Mục tiêu (theo mẫu)','Hạn hoàn thành','Điểm tối đa','Nguồn','Thao tác'],p.items.map(i=>{const t=B.templateFor(s,i);return [`${esc(i.name)}<small>${i.id} · ${i.criterion} · mẫu v${i.templateVersion}</small>`,`${compareLabel(t.compare)} ${esc(i.target)} ${esc(t.unit)}${t.compare==='between'?' đến '+esc(i.upper):''}`,date(i.due)+source('Hạn gốc: '+date(i.originalDue||i.due)),fmt(i.cap),esc(i.origin||'Áp dụng mẫu'),btn('Chi tiết','item-edit',`data-id="${i.id}"`)];}))}</div>`)+`<div class="card" id="plan-workflow"><h2>Kiểm tra và phê duyệt bảng chỉ tiêu</h2>${errors.length?`<div class="notice">${errors.length} mục cần bổ sung. ${esc(errors.slice(0,3).join(' '))}</div>`:'<div class="notice info">Phân bổ đủ 100 điểm, mẫu và mục tiêu hợp lệ.</div>'}<div class="actions">${btn('Trình duyệt bảng chỉ tiêu','plan-submit','id="plan-submit"','primary')}${btn('Duyệt bảng chỉ tiêu','plan-approve','id="plan-approve"')}${btn('Trả kế hoạch','plan-return')}${p!==s.plan?btn('Hủy bản điều chỉnh','cancel-adjust','','danger'):''}</div>${source('Đơn vị trình; người quản lý duyệt/trả. Bản chờ duyệt khóa sửa. Bản điều chỉnh không thay bản cũ trước khi duyệt.')}</div>`;}
function compareLabel(k){return {gte:'Ít nhất',lte:'Không quá',eq:'Bằng',between:'Trong khoảng',level:'Đạt mức'}[k]||'';}
function itemTemplate(t,index){return {id:'CT'+(index+1),templateId:t.id,templateVersion:t.version,criterion:t.criterion,name:t.name,target:t.measure==='level'?(t.levels.find(x=>x.pct===100)?.name||t.levels.at(-1)?.name):t.target,upper:t.upper,unit:s.org,due:s.config.deadline,originalDue:s.config.deadline,cap:s.criteria.find(c=>c.code===t.criterion).cap,requirement:t.definition,origin:'Áp dụng mẫu'};}
function reports(){return title(3,'Báo cáo kết quả','Nhập số thực tế, ngày hoàn thành và tài liệu kiểm chứng. Hệ thống tính điểm; người dùng không nhập điểm.',btn('Điền báo cáo ví dụ','fill-reports','id="fill-reports"')+btn('Gửi tất cả bản nháp','send-all','id="send-all"','primary'))+guide('Mở đúng chỉ tiêu → nhập số gốc → xem cách tính → gửi xác nhận → người xác nhận kiểm tra và xác nhận. Điểm nháp chỉ để xem trước.')+(s.plan.status!=='approved'?'<div class="notice">Kế hoạch chưa duyệt. Hoàn tất bước 2 trước khi báo cáo.</div>':'')+`<div class="card" id="report-table"><div class="actions"><input id="search" aria-label="Tìm báo cáo" placeholder="Tìm chỉ tiêu" style="max-width:350px">${btn('Xác nhận các báo cáo đang chờ','confirm-all','id="confirm-all"')}${btn('Xuất bảng kết quả','export-reports')}</div>${table(['Chỉ tiêu / mục tiêu','Kết quả / điểm','Ngày số liệu / hoàn thành','Trạng thái','Thao tác'],s.plan.items.map(i=>{const t=B.templateFor(s,i),box=s.reports[i.id]||{},r=box.draft||box.official,v=B.value(t,r),sc=B.score(t,i,r),off=box.official;return [`${esc(i.name)}<small>${compareLabel(t.compare)} ${esc(i.target)} ${esc(t.unit)} · tối đa ${fmt(i.cap)} điểm</small>`,`${typeof v==='string'?esc(v):fmt(v)} ${esc(t.unit)}<small>${r?'Điểm '+(r.status==='confirmed'?'chính thức':'xem trước')+': '+fmt(sc):'Chưa báo cáo · điểm —'}</small>${off&&box.draft?source('Bản chính thức trước: '+fmt(B.score(t,i,off))+' điểm'):''}`,`${date(r?.date)}<small>Hoàn thành: ${date(r?.completed)}</small>`,r?badge(r.status):'<span class="badge">Chưa báo cáo</span>',btn(r?'Cập nhật / xem':'Nhập kết quả','report-edit',`data-id="${i.id}"`)+(r?.status==='waiting'?btn('Xác nhận','report-confirm',`data-id="${i.id}"`)+btn('Trả bổ sung','report-return',`data-id="${i.id}"`):'')+btn('Lịch sử','report-history',`data-id="${i.id}"`)];}))}</div><div class="notice info">480 / 500 × 10 = 9,60 điểm, nhưng vẫn chưa đạt mục tiêu 500. Tổng số bằng 0 là “Chưa xác định”, không tự cho 0% hoặc 100%.</div>`;}
function officials(){return Object.fromEntries(Object.entries(s.reports).filter(([,b])=>b.official).map(([id,b])=>[id,b.official]));}
function assessment(){const calc=B.totals(s,officials()),snap=s.assessment.snapshot;const display=snap?B.totals({...s,plan:snap.plan,criteria:snap.criteria,templates:snap.templates},snap.reports):calc;return title(4,'Tự đánh giá','Tổng hợp từ kết quả đã xác nhận. Người lập kiểm tra căn cứ; người đứng đầu xác nhận rồi trình.',btn('Lưu nhận xét','save-notes','id="save-notes"')+btn('Chuyển người đứng đầu','to-head','id="to-head"','primary'))+guide('Đọc bảng điểm → kiểm tra điều kiện → ghi nhận xét → chuyển người đứng đầu → xác nhận và trình. Không nhập lại điểm tiêu chí.')+statebar()+`<div class="grid three"><div class="card" id="score-total"><span class="eyebrow">${snap?'Bản hồ sơ cố định':'Tổng hợp hiện tại'}</span><div class="stat">${fmt(display.total)} <small>/ 100</small></div>${display.complete?'<span class="badge ok">Đủ dữ liệu tính điểm</span>':'<span class="badge wait">Tổng tạm · chưa chốt</span>'}</div><div class="card"><span class="eyebrow">Dữ liệu còn thiếu</span><div class="stat">${display.missing.length}</div><p>Chỉ tiêu chưa có kết quả xác nhận.</p></div><div class="card"><span class="eyebrow">Trạng thái hồ sơ</span><h2 style="margin-top:15px">${badge(s.assessment.status)}</h2>${source('Người lập → người đứng đầu → thẩm định → công nhận.')}</div></div>`+tabs([['main','Bảng tự chấm'],['conditions','Điều kiện và hồ sơ'],['evidence','Minh chứng'],['history','Lịch sử']])+(tab==='conditions'?conditionsView(s.assessment.proposed,display.total):tab==='evidence'?evidenceView(snap?.reports||officials()):tab==='history'?history():`<div class="card" id="self-table">${table(['Mã','Tiêu chí','Điểm tối đa','Điểm tự đánh giá','Căn cứ'],s.criteria.map(c=>[c.code,c.title,fmt(c.cap),fmt(display.by[c.code]),btn('Xem nguồn','criterion-detail',`data-id="${c.code}"`)]))}</div><div class="card" id="self-notes"><h2>Nhận xét và mức đề xuất</h2><div class="formgrid">${textfield('Ưu điểm / kết quả nổi bật','strength',s.assessment.strength,'Người lập tự nhập dựa trên kết quả thực tế.')}${textfield('Hạn chế / việc cần cải thiện','weakness',s.assessment.weakness)}${textfield('Giải trình thêm','notes',s.assessment.notes)}${optsRating('proposed',s.assessment.proposed)}</div><div class="actions">${btn('Kiểm tra điều kiện','conditions-tab')}${btn('Xác nhận và trình','submit-assessment','id="submit-assessment"','primary')}${btn('Trả về người lập','head-return')}</div><p class="muted">Thiếu kết quả xác nhận, phân bổ hoặc tài liệu bắt buộc sẽ chặn trình. Điểm chưa phù hợp mức đề xuất được chuyển để người có thẩm quyền xem xét, không tự đổi điểm.</p></div>`);}
function taskView(){const m=B.metrics(s);return `<div class="card"><h2>Nhiệm vụ làm căn cứ (dữ liệu liên kết)</h2><p>${m.done}/${m.n} hoàn thành; ${m.on}/${m.n} đúng hạn, đủ chất lượng và hiệu quả; ${m.ex}/${m.n} vượt yêu cầu (${fmt(m.ex/m.n*100)}%).</p>${table(['Mã nhiệm vụ','Nguồn','Nghiệm thu','Đúng hạn / chất lượng / hiệu quả','Vượt yêu cầu'],s.tasks.map(t=>[t.id,t.kind==='plan'?'Trong kế hoạch':'Phát sinh',t.accepted?'Đã nghiệm thu':'Chưa',`${t.timely?'Có':'Chưa'} / ${t.quality?'Có':'Chưa'} / ${t.effective?'Có':'Chưa'}`,t.exceed?'Được xác nhận':'Không']))}<p class="muted">Đọc từ dữ liệu nhiệm vụ dùng chung theo năm; mỗi mã chỉ đếm một lần. Số chỉ tiêu không thay số nhiệm vụ. Demo có 12 nhiệm vụ ví dụ, không xây thêm phân hệ công việc.</p></div>`;}
function conditionsView(r,p){const state=s.assessment.snapshot?{...s,tasks:s.assessment.snapshot.tasks,conditions:s.assessment.snapshot.conditions}:s;const rows=B.eligibility(state,r,p),m=B.metrics(state);return `<div class="card" id="conditions"><h2>Điều kiện cho mức ${rating[r]}</h2>${table(['Điều kiện kiểm tra','Kết quả / cách lấy'],rows.map(x=>[x.name,`<span class="badge ${x.ok===true?'ok':x.ok===false?'bad':'wait'}">${x.ok===true?'Đáp ứng':x.ok===false?'Cần xem xét':'Chưa xác định'}</span>`]))}<p class="muted">Nguồn: nhiệm vụ đã nghiệm thu, kết quả cấp dưới, hồ sơ khắc phục và kết luận đã xác minh. Phản ánh chưa phải kết luận sai phạm.</p><div class="notice">Ví dụ ${m.ex}/${m.n} nhiệm vụ vượt yêu cầu = ${fmt(m.ex/m.n*100)}%. Vượt mục tiêu số không tự động được coi là nhiệm vụ vượt yêu cầu.</div>${btn('Xem / bổ sung hồ sơ căn cứ','condition-record','id="condition-record"')}${(s.records||[]).length?table(['Loại hồ sơ','Nội dung / tài liệu','Người xử lý'],s.records.map(x=>[esc(x['record-type']),esc(x['record-text'])+'<small>'+esc(x['record-evidence'])+'</small>',esc(x.by)])):''}</div>${taskView()}`;}
function evidenceView(rs){return `<div class="card"><h2>Tài liệu kiểm chứng theo từng chỉ tiêu</h2>${table(['Chỉ tiêu','Tài liệu / nguồn','Người xác nhận / ngày'],s.plan.items.map(i=>[esc(i.name),esc(rs[i.id]?.evidence||'Chưa có tài liệu'),esc(rs[i.id]?.confirmedBy||'—')+'<small>'+esc(rs[i.id]?.confirmedAt||'—')+'</small>']))}<p class="muted">Tệp demo chỉ lưu tên trên trình duyệt. Bản triển khai phải lưu tệp thực, quyền truy cập và phiên bản tài liệu trên máy chủ.</p></div>`;}
function review(){const a=s.assessment,snap=a.snapshot;let rs=snap?.reports||{},ss=snap?{...s,plan:snap.plan,criteria:snap.criteria,templates:snap.templates}:s,sc=B.totals(ss,rs),rev=B.totals(ss,{...rs,...s.review.reports}),q=B.quota(s);return title(5,'Thẩm định và công nhận','Giữ nguyên bản tự đánh giá. Người thẩm định xử lý từng chỉ tiêu, người công nhận quyết định mức cuối.',btn('Khởi tạo bản thẩm định','init-review','id="init-review"','primary'))+guide('Mở bản đã trình → kiểm chứng → nhập số liệu thẩm định riêng → hoàn tất → kiểm điều kiện và hạn mức → công nhận → thông báo.')+statebar()+(!snap?'<div class="notice">Hồ sơ chưa được người đứng đầu trình. Hoàn tất bước 4 trước khi thẩm định.</div>':'')+`<div class="grid three"><div class="card"><span class="eyebrow">Điểm bản đã trình</span><div class="stat">${fmt(sc.total)}</div><p>${snap?'Dữ liệu đã được lưu cố định.':'Chưa có bản trình.'}</p></div><div class="card"><span class="eyebrow">Điểm thẩm định riêng</span><div class="stat">${fmt(rev.total)}</div>${badge(s.review.status)}</div><div class="card" id="quota"><span class="eyebrow">Hạn mức xuất sắc</span><div class="stat">${q.excellent} / ${q.max}</div><p>${q.good} đơn vị hoàn thành tốt × ${s.config.quota}% → bỏ phần lẻ.</p>${source('Cùng năm và cấp công nhận; không cộng xuất sắc vào mẫu số. Demo có 20 hồ sơ hoàn thành tốt ví dụ.')}</div></div>`+tabs([['main','Đối chiếu điểm'],['conditions','Điều kiện'],['history','Lịch sử']])+(tab==='conditions'?conditionsView(s.review.proposed,rev.total):tab==='history'?history():`<div class="card" id="review-table">${table(['Tiêu chí','Tự đánh giá','Thẩm định','Thao tác'],s.criteria.map(c=>[c.code+' · '+c.title,fmt(sc.by[c.code]),fmt(rev.by[c.code]),btn('Thẩm định chỉ tiêu','review-criterion',`data-id="${c.code}"`)]))}</div><div class="card" id="review-actions"><h2>Ý kiến thẩm định</h2>${textfield('Ý kiến (căn cứ đối chiếu và đề xuất xử lý)','review-opinion',s.review.opinion)}${optsRating('review-rating',s.review.proposed)}<div class="actions">${btn('Lưu thẩm định','save-review')}${btn('Yêu cầu bổ sung','return-assessment')}${btn('Hoàn tất thẩm định','finish-review','id="finish-review"','primary')}${btn('Công nhận kết quả','recognize','id="recognize"')}${btn('Thông báo kết quả','notify','id="notify"')}</div>${source('Lưu không đồng nghĩa hoàn tất. Điểm khác tự chấm cần lý do và tài liệu. Công nhận khóa hồ sơ; thông báo là bước riêng.')}</div>`);}
function results(){const d=s.decision,snap=s.assessment.snapshot,ss=snap?{...s,plan:snap.plan,criteria:snap.criteria,templates:snap.templates}:s,rs=snap?.reports||officials(),self=B.totals(ss,rs),rv=B.totals(ss,{...rs,...s.review.reports});return title(6,'Kết quả và in','Chỉ quyết định đã công nhận là kết quả chính thức. Tự đánh giá và thẩm định vẫn hiển thị riêng.',btn('Xuất toàn bộ bảng (CSV / Excel)','export-results','id="export-results"')+btn('Thông tin phiếu in','print-info','id="print-info"')+btn('Xem trước phiếu in','print-preview','id="print-preview"','primary'))+guide('Kiểm tra trạng thái → mở quyết định → bổ sung thông tin in theo vai trò → xem trước → in hoặc lưu PDF.')+`<div class="card" id="result-summary"><div class="eyebrow">${d?'Kết quả chính thức':'Hồ sơ đang xử lý'}</div><h2 style="margin-top:8px">${esc(s.org)} · ${s.year}</h2><div class="stat">${d?rating[d.rating]:'Chưa công nhận'}</div><p>Điểm tự đánh giá: ${fmt(self.total)} · Thẩm định: ${s.review.status==='draft'?'—':fmt(rv.total)}</p>${d?`<p>Quyết định ${esc(d.number)} · ngày ${date(d.date)} · người ký ${esc(d.signer)}</p><p>Căn cứ: ${esc(d.basis)}<br>Tài liệu: ${esc(d.file)}</p>${badge('recognized')} ${s.notified?'<span class="badge ok">Đã thông báo</span>':'<span class="badge wait">Chưa thông báo</span>'}`:'<p class="muted">Không dùng tổng tự chấm để hiển thị thành kết quả chính thức.</p>'}</div><div class="card"><h2>Bảng kết quả theo chỉ tiêu</h2><input id="search" placeholder="Lọc tên chỉ tiêu" aria-label="Lọc kết quả" style="max-width:350px;margin-bottom:15px">${table(['Chỉ tiêu / mẫu','Mục tiêu','Kết quả tự đánh giá','Điểm tự chấm','Điểm thẩm định'],ss.plan.items.map(i=>{const t=B.templateFor(ss,i),r=rs[i.id];return [esc(i.name)+'<small>'+i.criterion+' · v'+i.templateVersion+'</small>',esc(i.target)+' '+esc(t.unit),fmt(B.value(t,r)),fmt(B.score(t,i,r)),s.review.status==='draft'?'—':fmt(B.score(t,i,s.review.reports[i.id]||r))];}))}</div>`;}
function history(){return `<div class="card">${table(['Thời gian','Người xử lý / vai trò','Thao tác','Phiên bản kế hoạch'],s.log.map(x=>[esc(x.at),esc(x.role),esc(x.action),'v'+x.planVersion]))}</div>`;}
function modal(name,body,footer){stopTour();closeModal(true);dialogDirty=false;const el=document.createElement('div');el.className='dialogback';el.innerHTML=`<section class="dialog" role="dialog" aria-modal="true" aria-label="${esc(name)}"><div class="dialoghead"><h2 style="margin:0">${esc(name)}</h2>${btn('×','close','aria-label="Đóng"')}</div><div class="dialogbody">${body}<div id="modal-error" role="alert"></div></div><div class="dialogfoot">${btn('Hủy / đóng','close')}${footer||''}</div></section>`;document.body.append(el);el.addEventListener('input',()=>dialogDirty=true);el.addEventListener('change',()=>dialogDirty=true);el.querySelector('input,select,textarea,button')?.focus();}
function closeModal(force=false){if(!force&&dialogDirty&&!confirm('Có thay đổi chưa lưu. Đóng và bỏ thay đổi?'))return false;$('.dialogback')?.remove();dialogDirty=false;return true;}
function error(t){$('#modal-error').innerHTML=`<div class="error">${Array.isArray(t)?t.map(esc).join('<br>'):esc(t)}</div>`;}
function form(){const o={};$('.dialog').querySelectorAll('input,select,textarea').forEach(x=>{if(x.id)o[x.id]=x.type==='checkbox'?x.checked:x.type==='number'?(x.value===''?null:Number(x.value)):x.value;});return o;}
let editTemplate=null,editItem=null,editReport=null,reviewItem=null;
function templateEditor(t){editTemplate=structuredClone(t);modal('Mẫu chỉ tiêu · '+(t.id||'mới'),`<p class="notice info">Tên và ví dụ giúp người dùng hiểu. Cách đo/chấm sẽ được kế thừa khi tạo chỉ tiêu năm.</p><div class="formgrid">${field('Tên chỉ tiêu (kết quả cần theo dõi)','tname',t.name)}${select('Thuộc tiêu chí (lấy khung 11 tiêu chí)','tcriterion',Object.fromEntries(s.criteria.map(c=>[c.code,c.code+' · '+c.title])),t.criterion)}${field('Đơn vị tính (ví dụ: %, hồ sơ, tỷ)','tunit',t.unit)}${field('Mục tiêu gợi ý (đơn vị có thể nhập lại)','ttarget',t.target,'number')}${select('Cách đo (nhập số hay chọn mức)','tmeasure',{direct:'Giá trị trực tiếp',ratio:'Số đạt / tổng số → %',level:'Mức mô tả'},t.measure)}${select('Cách chấm (tính điểm từ kết quả)','tscoring',{completion:'Mức hoàn thành',range:'Khoảng kết quả',level:'Mức mô tả'},t.scoring)}${select('So sánh mục tiêu (khi nào được coi là đạt)','tcompare',{gte:'Ít nhất (≥)',lte:'Không quá (≤)',eq:'Bằng (=)',between:'Trong khoảng',level:'Đạt mức'},t.compare)}${field('Cận trên mục tiêu (khi chọn trong khoảng)','tupper',t.upper,'number','Ví dụ: cận dưới 95, cận trên 100.')}${select('Gộp nhiều kỳ (tránh đếm trùng)','taggregate',{sum:'Cộng số phát sinh không trùng',last:'Lấy số lũy kế lần chốt cuối',ratio:'Cộng số đạt / tổng số rồi chia'},t.aggregate)}${select('Không phát sinh / không áp dụng (quy tắc mẫu)','tnoData',{review:'Chưa xác định · chuyển xem xét'},t.noData)}${field('Nguồn số liệu (lấy từ báo cáo nào)','tsource',t.source)}${select('Người / vai trò xác nhận (chọn trong phân công)','tverifier',{'Người xác nhận số liệu':'Người xác nhận số liệu'},t.verifier,'Bản thật lấy danh sách tài khoản/vai trò được phân quyền.')}${textfield('Phạm vi thống kê (đếm gì, không đếm gì)','tdefinition',t.definition)}${textfield('Chuẩn vượt yêu cầu (phải có nghiệm thu, không suy từ số cao)','texceed',t.exceed)}${check('Bắt buộc tài liệu kiểm chứng','tevidence',t.evidence)}</div><div id="score-fields"></div><div class="card" style="background:#f7faf4"><h3>Thử tính trước khi duyệt</h3>${field('Kết quả thử (số gốc theo đơn vị tính / tên mức)','trial',100)}${field('Mục tiêu thử (ví dụ 100 hoặc Đạt)','trial-target',100)}${field('Điểm tối đa thử (điểm, ví dụ 10)','trial-cap',10,'number')}${btn('Thử tính','trial','id="trial-button"')}<p id="trial-result" aria-live="polite"></p></div><p class="muted">Mẫu đã dùng: lưu thành phiên bản mới, không ghi đè bản cũ. Nháp chưa cho đơn vị áp dụng.</p>`,btn('Hướng dẫn các trường','tour-template')+btn('Lưu mẫu nháp','template-save','id="template-save"','primary'));renderScoreFields();}
function renderScoreFields(){const scoring=$('#tscoring').value;$('#score-fields').innerHTML=scoring==='range'?`<h3>Khoảng kết quả (theo giá trị đo, không phải % hoàn thành)</h3><p class="muted">Ô trống: không giới hạn. Chọn “Lấy cận” để bao gồm giá trị đúng ở biên. Phải phủ từ 0 trở lên trong demo.</p><div id="ranges">${editTemplate.ranges.map(rangeRow).join('')}</div>${btn('+ Thêm khoảng','range-add')}`:scoring==='level'?`<h3>Mức mô tả và tỷ lệ điểm</h3><div id="levels">${editTemplate.levels.map(levelRow).join('')}</div>${btn('+ Thêm mức','level-add')}`:'<div class="notice info">Điểm = kết quả ÷ mục tiêu × điểm tối đa; chặn tại điểm tối đa. Chỉ dùng cho số, mục tiêu > 0 và càng cao càng tốt.</div>';$('#tupper').closest('.field').hidden=$('#tcompare').value!=='between';$('#ttarget').closest('.field').hidden=$('#tmeasure').value==='level';}
function rangeRow(r){return `<div class="range-row formgrid card"><div>${field('Cận dưới (ví dụ: 95)','',r.lo,'number')}${check('Lấy giá trị tại cận dưới','',r.li)}</div><div>${field('Cận trên (ví dụ: 100; trống = không giới hạn)','',r.hi,'number')}${check('Lấy giá trị tại cận trên','',r.ui)}</div>${field('Tỷ lệ điểm (% điểm tối đa, 0–100)','',r.pct,'number')}${btn('Xóa khoảng','range-remove')}</div>`;}
function levelRow(r){return `<div class="level-row formgrid">${field('Tên mức (ví dụ: Đạt một phần)','',r.name)}${field('Tỷ lệ điểm (% điểm tối đa)','',r.pct,'number')}${btn('Xóa mức','level-remove')}</div>`;}
function readTemplate(){const f=form(),t={...editTemplate,name:f.tname,criterion:f.tcriterion,unit:f.tunit,target:f.ttarget,upper:f.tupper,measure:f.tmeasure,scoring:f.tscoring,compare:f.tcompare,aggregate:f.taggregate,noData:f.tnoData,source:f.tsource,verifier:f.tverifier,definition:f.tdefinition,exceed:f.texceed,evidence:f.tevidence};if(t.scoring==='range')t.ranges=[...document.querySelectorAll('.range-row')].map(r=>{let n=r.querySelectorAll('input[type=number]'),c=r.querySelectorAll('input[type=checkbox]');return {lo:n[0].value===''?null:+n[0].value,hi:n[1].value===''?null:+n[1].value,pct:n[2].value===''?null:+n[2].value,li:c[0].checked,ui:c[1].checked};});if(t.scoring==='level')t.levels=[...document.querySelectorAll('.level-row')].map(r=>({name:r.querySelector('input[type=text]').value,pct:r.querySelector('input[type=number]').value===''?null:+r.querySelector('input[type=number]').value}));return t;}
function templateErrors(t){const e=[];if(!t.name.trim()||!t.unit.trim()||!t.definition.trim()||!t.source.trim()||!t.verifier.trim())e.push('Thiếu tên, đơn vị tính, phạm vi, nguồn hoặc người xác nhận.');if(t.scoring==='completion'&&(t.measure==='level'||t.compare!=='gte'||!(t.target>0)))e.push('Mức hoàn thành chỉ dùng cho số, càng cao càng tốt và mục tiêu > 0.');if((t.measure==='level')!==(t.scoring==='level')||t.measure==='level'&&t.compare!=='level')e.push('Cách đo mức mô tả cần cách chấm và so sánh theo mức.');if(t.measure==='ratio'&&t.aggregate!=='ratio')e.push('Tỷ lệ phải gộp bằng cộng số đạt / tổng số.');if(t.scoring==='range'){const x=B.validateRanges(t.ranges);if(x)e.push(x);}if(t.scoring==='level'&&(!t.levels.length||t.levels.some(x=>!x.name.trim()||x.pct===null||x.pct<0||x.pct>100)||new Set(t.levels.map(x=>x.name)).size!==t.levels.length))e.push('Mức mô tả phải có tên không trùng và tỷ lệ từ 0–100.');if(t.compare==='between'&&(t.upper===null||t.upper<t.target))e.push('Cận trên mục tiêu phải ≥ cận dưới.');return e;}
function itemEditor(i){editItem=i;const p=effectivePlan(),t=B.templateFor(s,i);modal('Chỉ tiêu năm · '+(i.id||'mới'),`<div class="notice info">Kế thừa mẫu ${t.id} v${t.version}: ${measureName(t.measure)}, ${scoreName(t.scoring)}, ${compareLabel(t.compare)}. Nguồn: ${esc(t.source)}. Xác nhận: ${esc(t.verifier)}.</div><div class="formgrid">${field('1. Tên chỉ tiêu (lấy từ mẫu, có thể diễn giải rõ)','iname',i.name)}${field('2. Thuộc tiêu chí (lấy mẫu)','icriterion',i.criterion,'text','','readonly')}${field('3. Đơn vị thực hiện (lấy đơn vị trong phạm vi quyền)','iunit',s.org,'text','','readonly')}${field('4. Đơn vị tính (lấy mẫu)','iunitmeasure',t.unit,'text','','readonly')}${t.measure==='level'?select('5. Mục tiêu (mức cần đạt)','itarget',Object.fromEntries(t.levels.map(x=>[x.name,x.name])),i.target):field('5. Mục tiêu (số cần đạt; '+compareLabel(t.compare)+')','itarget',i.target,'number')}${t.compare==='between'?field('Cận trên mục tiêu (giới hạn trên của khoảng)','iupper',i.upper,'number'):''}${field('6. Kỳ đánh giá (năm đang chọn)','iyear',s.year,'number','','readonly')}${field('7. Hạn hoàn thành (ngày cuối phải hoàn tất)','idue',i.due,'date')}${field('Điểm tối đa (lấy phân bổ, chỉ người cấu hình sửa)','icap',i.cap,'number','','readonly')}${textfield('8. Mô tả yêu cầu (đầu ra, phạm vi, chất lượng)','irequirement',i.requirement)}</div>${p.status==='approved'||p.status==='pending'?'<p class="notice">Bản này đã duyệt/đang chờ duyệt, chỉ được xem. Muốn thay đổi bản đã duyệt, tạo đề nghị điều chỉnh.</p>':''}`,btn('Lưu nháp','item-save','id="item-save"','primary'));}
function reportEditor(i,isReview=false){const t=B.templateFor(s,i),box=s.reports[i.id]||{},r=isReview?(s.review.reports[i.id]||s.assessment.snapshot?.reports[i.id]||{}):(box.draft||box.official||{});if(t.id==='MB2'&&!isReview){const m=B.metrics(s);r.numerator=m.done;r.total=m.n;}editReport=i;reviewItem=isReview?i:null;modal(isReview?'Số liệu thẩm định riêng':'Báo cáo · '+i.name,`<div class="notice info"><b>${esc(i.name)}</b><br>Mục tiêu: ${compareLabel(t.compare)} ${esc(i.target)} ${esc(t.unit)}. Tối đa ${fmt(i.cap)} điểm. ${scoreName(t.scoring)}.<br>Nguồn: ${esc(t.source)} · người xác nhận: ${esc(t.verifier)}</div>${r.returnReason?`<div class="notice">Cần bổ sung: ${esc(r.returnReason)}</div>`:''}<div class="formgrid">${t.measure==='ratio'?field('Số đạt (ví dụ: 1.980 hồ sơ)','rnumerator',r.numerator,'number',t.id==='MB2'?'Lấy nhiệm vụ đã nghiệm thu; không nhập tay.':'',t.id==='MB2'&&!isReview?'readonly':'')+field('Tổng số (ví dụ: 2.000; phải > 0)','rtotal',r.total,'number',t.id==='MB2'?'Tổng nhiệm vụ tổ chức, mỗi mã đếm một lần.':'',t.id==='MB2'&&!isReview?'readonly':''):t.measure==='level'?select('Mức thực tế (chọn mô tả đã duyệt)','rlevel',Object.fromEntries(t.levels.map(x=>[x.name,x.name])),r.level):field('Giá trị thực tế ('+esc(t.unit)+'; số không âm)','rvalue',r.value,'number')}${field('Ngày số liệu (dữ liệu tính đến ngày này)','rdate',r.date||'2026-10-13','date')}${field('Ngày hoàn thành thực tế (khác ngày nhập báo cáo)','rcompleted',r.completed||'2026-10-12','date')}${field('Kỳ báo cáo (ví dụ: tháng 10 / cả năm)','rperiod',r.period||'Cả năm 2026')}${field('Tài liệu kiểm chứng (tên, mã hồ sơ hoặc link)','revidence',r.evidence||'','text','Demo lưu tên/link. Bản triển khai lưu tài liệu thực theo từng báo cáo.')}${field('Chọn tệp (demo chỉ lưu tên tệp)','rfile','','file')}${check('Đáp ứng yêu cầu chất lượng và phạm vi thống kê','rquality',r.quality)}${textfield('Giải trình / phạm vi số liệu','rnotes',r.notes||'')}${isReview?textfield('Lý do điều chỉnh (bắt buộc khi khác bản tự đánh giá)','rreason',s.review.reasons[i.id]||''):''}</div><div class="notice info" id="score-preview" aria-live="polite"></div><p class="muted">Sửa báo cáo đã xác nhận tạo bản mới. Bản chính thức trước vẫn được giữ đến khi bản mới xác nhận.</p>`,btn('Hướng dẫn nhập kết quả','tour-report')+btn(isReview?'Lưu số liệu thẩm định':'Lưu nháp',isReview?'review-item-save':'report-save','id="report-save"')+(!isReview?btn('Gửi xác nhận','report-send','id="report-send"','primary'):''));previewReport();}
function readReport(){const f=form();if(editReport?.templateId==='MB2'&&!reviewItem){const m=B.metrics(s);f.rnumerator=m.done;f.rtotal=m.n;}return {value:f.rvalue,numerator:f.rnumerator,total:f.rtotal,level:f.rlevel,date:f.rdate,completed:f.rcompleted,period:f.rperiod,evidence:f.revidence,quality:f.rquality,notes:f.rnotes,status:'draft'};}
function previewReport(){if(!$('#score-preview'))return;const i=editReport,t=B.templateFor(s,i),r=readReport(),v=B.value(t,r),n=B.score(t,i,r);$('#score-preview').innerHTML=`Kết quả: <b>${typeof v==='string'?esc(v):fmt(v)} ${esc(t.unit)}</b> · Điểm xem trước: <b>${fmt(n)} / ${fmt(i.cap)}</b><br>${v===null?'Chưa xác định. Kiểm tra số gốc.':B.achieved(t,i.target,i.upper,v)?'Đạt mục tiêu (còn cần kiểm tra chất lượng).':'Chưa đạt mục tiêu.'}${t.measure==='ratio'?'<br>Tỷ lệ = số đạt ÷ tổng số × 100%.':''}`;}
function saveReport(send){if(!guard('unit'))return;if(s.plan.status!=='approved'||s.assessment.status!=='draft'){error('Chỉ báo cáo kế hoạch đã duyệt khi hồ sơ còn ở bước tự đánh giá.');return;}const box=s.reports[editReport.id]||{};if(box.draft?.status==='waiting'){error('Báo cáo đang chờ xác nhận; cần được trả trước khi sửa.');return;}const r=readReport();if(send){const e=B.reportErrors(B.templateFor(s,editReport),r);if(e.length){error(e);return;}r.status='waiting';}box.draft=r;s.reports[editReport.id]=box;save((send?'Gửi xác nhận: ':'Lưu báo cáo nháp: ')+editReport.name);closeModal(true);render();toast(send?'Đã gửi người xác nhận.':'Đã lưu nháp.');}
function confirmReport(id){const i=s.plan.items.find(x=>x.id===id),box=s.reports[id],r=box?.draft;if(!r||r.status!=='waiting')return false;const e=B.reportErrors(B.templateFor(s,i),r);if(e.length){toast(i.name+': '+e.join(' '));return false;}box.history=box.history||[];if(box.official)box.history.push(structuredClone(box.official));box.official={...r,status:'confirmed',confirmedBy:roles[s.role],confirmedAt:new Date().toLocaleString('vi-VN')};delete box.draft;return true;}
function notesFromPage(){if(!allowed('unit')||s.assessment.status!=='draft')return;if($('#strength'))Object.assign(s.assessment,{strength:$('#strength').value,weakness:$('#weakness').value,notes:$('#notes').value,proposed:$('#proposed').value});}
function reviewFromPage(){if(!allowed('reviewer')||s.assessment.status!=='submitted')return;if($('#review-opinion')){s.review.opinion=$('#review-opinion').value;s.review.proposed=$('#review-rating').value;}}
function aggregateReports(){const rs=officials(),c=B.totals(s,rs);return {rs,c};}
function snapshot(){return structuredClone({year:s.year,org:s.org,config:s.config,plan:s.plan,criteria:s.criteria,templates:s.templates,reports:officials(),tasks:s.tasks,conditions:s.conditions,printInfo:s.printInfo||null,notes:{...s.assessment,snapshot:null},at:new Date().toLocaleString('vi-VN')});}
function sampleReports(){for(const [n,i] of s.plan.items.entries()){const t=B.templateFor(s,i),r={value:i.target*.8,numerator:1600,total:2000,level:'Đạt một phần',date:'2026-10-13',completed:'2026-10-12',period:'Cả năm 2026',quality:true,evidence:'Báo cáo minh họa '+i.id+' (dữ liệu mẫu)',notes:'Dữ liệu ví dụ để thử luồng, không phải số liệu thực.',status:'draft'};if(n===0&&t.measure==='direct')r.value=480;if(t.measure==='level')r.level=t.levels.find(x=>x.pct===50)?.name||t.levels[0]?.name;if(t.id==='MB2'){const m=B.metrics(s);r.numerator=m.done;r.total=m.n;r.notes='Số nhiệm vụ được lấy từ dữ liệu nghiệm thu, mỗi mã một lần.';}s.reports[i.id]={draft:r};}}
function applyTemplates(){const p=effectivePlan(),latest=s.templates.filter(t=>t.status==='approved'&&!s.templates.some(x=>x.id===t.id&&x.status==='approved'&&x.version>t.version));p.items=latest.map(itemTemplate);for(const c of s.criteria){const a=p.items.filter(i=>i.criterion===c.code);for(const i of a)i.cap=c.cap/a.length;}}
const handlers={
 'close':()=>closeModal(), 'tab':el=>{tab=el.dataset.tab;render();}, 'tour':()=>startTour(),
 'reset':()=>{if(confirm('Xóa dữ liệu demo đang lưu trên trình duyệt và làm lại từ đầu?')){s=B.seed();save('Khởi tạo lại dữ liệu demo');render();}},
 'scenario':()=>{if(!confirm('Nạp hồ sơ ví dụ sẽ thay dữ liệu demo đang có. Tiếp tục?'))return;s=B.seed();applyTemplates();s.plan.status='approved';sampleReports();for(const id of Object.keys(s.reports)){s.reports[id].draft.status='waiting';confirmReport(id);}s.assessment.strength='Các nhiệm vụ đều được nghiệm thu đúng hạn.';s.assessment.weakness='Một số chỉ tiêu mới đạt 80% mục tiêu; 3/12 nhiệm vụ vượt yêu cầu.';save('Nạp bộ dữ liệu minh họa đã xác nhận');render();toast('Đã nạp. Mở bước 4 để tự đánh giá.');},
 'edit-period':()=>modal('Kỳ đánh giá và bản cấu hình',`<div class="formgrid">${field('Năm (kỳ xếp loại chính thức)','year',s.year,'number','','readonly')}${field('Hạn chốt hồ sơ (ngày cuối được nộp)','deadline',s.config.deadline,'date')}${field('Ngày áp dụng (bắt đầu hiệu lực)','effective',s.config.effective,'date')}${field('Căn cứ áp dụng (tên / số văn bản)','basis',s.config.basis)}${field('Hạn mức xuất sắc (%; thông thường 20, tối đa 25)','quota-rate',s.config.quota,'number')}${field('Quyết định cho tỷ lệ trên 20% (bắt buộc nếu tăng)','quota-basis',s.config.quotaBasis||'')}</div><p class="muted">Nếu đã có kế hoạch duyệt, không sửa cấu hình trong năm. Tạo năm mới hoặc phiên bản và quy trình điều chỉnh ở bản triển khai.</p>`,btn('Lưu cấu hình','period-save','','primary')),
 'period-save':()=>{if(!guard('admin'))return;const f=form();if(s.plan.status==='approved'){error('Kế hoạch đã duyệt. Không thay quy tắc đang áp dụng.');return;}if(!f.deadline||!f.effective||!f.basis.trim()||f.effective>f.deadline||f['quota-rate']<0||f['quota-rate']>25||f['quota-rate']===null||(f['quota-rate']>20&&!f['quota-basis'].trim())){error('Kiểm tra ngày, căn cứ và tỷ lệ 0–25%; trên 20% cần quyết định.');return;}s.config={...s.config,deadline:f.deadline,effective:f.effective,basis:f.basis,quota:f['quota-rate'],quotaBasis:f['quota-basis'],version:s.config.version+1,status:'draft'};save('Lưu cấu hình nháp');closeModal(true);render();},
 'new-year':()=>{if(!guard('admin'))return;modal('Sao chép năm mới',field('Năm mới (khác năm hiện tại)','next-year',s.year+1,'number')+'<p>Hồ sơ năm hiện tại được lưu trong kho demo. Năm mới sao chép mẫu và khung sang nháp, không sao chép kết quả hoặc quyết định.</p>',btn('Tạo năm mới','year-create','','primary'));},
 'year-create':()=>{const y=form()['next-year'];if(!Number.isInteger(y)||y<=s.year||y>2100){error('Nhập năm mới lớn hơn năm hiện tại, tối đa 2100.');return;}try{localStorage.setItem(KEY+'-archive-'+s.year,JSON.stringify(s));}catch{error('Không thể lưu hồ sơ năm cũ.');return;}const old=s;s=B.seed();s.year=y;s.role='admin';s.criteria=structuredClone(old.criteria);s.templates=structuredClone(old.templates.filter(t=>t.status==='approved')).map(t=>({...t,status:'draft'}));s.config={...old.config,status:'draft',version:1,deadline:y+'-12-14',effective:y+'-01-01'};s.otherFinals=[];save('Sao chép năm '+y+' sang nháp');closeModal(true);render();},
 'template-add':()=>{if(!guard('admin'))return;templateEditor({...B.seed().templates[0],id:null,name:'',status:'draft',version:1});},
 'template-edit':el=>templateEditor(s.templates.find(t=>t.id===el.dataset.id&&t.version===+el.dataset.version)),
 'template-save':()=>{if(!guard('admin'))return;const t=readTemplate(),e=templateErrors(t);if(e.length){error(e);return;}if(t.status==='pending'){error('Mẫu đang chờ duyệt, phải trả bổ sung trước khi sửa.');return;}if(!t.id){t.id='M'+Date.now().toString().slice(-7);t.version=1;s.templates.push({...t,status:'draft'});}else if(t.status==='approved'){t.version=Math.max(...s.templates.filter(x=>x.id===t.id).map(x=>x.version))+1;s.templates.push({...t,status:'draft'});}else{s.templates[s.templates.findIndex(x=>x.id===t.id&&x.version===t.version)]={...t,status:'draft'};}save('Lưu mẫu nháp '+t.id+' v'+t.version);closeModal(true);render();},
 'template-submit':el=>{if(!guard('admin'))return;const t=s.templates.find(t=>t.id===el.dataset.id&&t.version===+el.dataset.version),e=templateErrors(t);if(e.length){toast(e.join(' '));return;}t.status='pending';save('Trình mẫu '+t.id);render();},
 'config-submit':()=>{if(!guard('admin'))return;s.config.status='pending';save('Trình cấu hình kỳ');render();},
 'config-approve':()=>{if(!guard('admin'))return;if(s.config.status!=='pending')return;s.config.status='approved';save('Duyệt cấu hình kỳ');render();},
 'template-approve':el=>{if(!guard('admin'))return;const t=s.templates.find(t=>t.id===el.dataset.id&&t.version===+el.dataset.version);t.status='approved';save('Duyệt mẫu '+t.id+' v'+t.version);render();},
 'template-return':el=>{if(!guard('admin'))return;const why=prompt('Lý do trả mẫu (bắt buộc):');if(!why?.trim())return;const t=s.templates.find(t=>t.id===el.dataset.id&&t.version===+el.dataset.version);t.status='returned';save('Trả mẫu '+t.id+': '+why);render();},
 'range-add':()=>{const e=document.createElement('div');e.innerHTML=rangeRow({lo:100,hi:null,li:true,ui:false,pct:100});$('#ranges').append(e.firstElementChild);dialogDirty=true;},
 'range-remove':el=>{el.closest('.range-row').remove();dialogDirty=true;},
 'level-add':()=>{const e=document.createElement('div');e.innerHTML=levelRow({name:'',pct:0});$('#levels').append(e.firstElementChild);dialogDirty=true;},
 'level-remove':el=>{el.closest('.level-row').remove();dialogDirty=true;},
 'trial':()=>{const t=readTemplate(),f=form(),e=templateErrors(t);if(e.length){$('#trial-result').textContent=e.join(' ');return;}const r=t.measure==='level'?{level:f.trial}:{value:Number(f.trial),numerator:Number(f.trial),total:100};const i={target:t.measure==='level'?f['trial-target']:Number(f['trial-target']),upper:t.upper,cap:f['trial-cap']};$('#trial-result').textContent='Điểm xem trước: '+fmt(B.score(t,i,r))+' / '+fmt(i.cap)+'. Kết quả đo '+String(B.value(t,r))+' '+t.unit+'.';},
 'apply-set':()=>{if(!guard('unit','admin'))return;const p=effectivePlan();if(!['draft','returned'].includes(p.status)){toast('Chỉ áp dụng mẫu vào bản nháp.');return;}if(p.items.length&&!confirm('Thay danh sách nháp bằng bộ mẫu đã duyệt?'))return;applyTemplates();save('Áp dụng bộ mẫu vào kế hoạch nháp');render();},
 'item-add':()=>{if(!guard('unit','admin'))return;modal('Chọn mẫu đã duyệt',select('Mẫu (kế thừa cách đo/chấm)','selected-template',Object.fromEntries(s.templates.filter(t=>t.status==='approved').map(t=>[t.id+'@'+t.version,t.name+' · v'+t.version])),'')+'<p>Thêm chỉ tiêu không tự chia lại điểm cũ. Sau khi thêm hãy kiểm tra phân bổ.</p>',btn('Chọn mẫu','item-from-template','','primary'));},
 'item-from-template':()=>{const p=effectivePlan();if(!['draft','returned'].includes(p.status)){error('Kế hoạch không ở trạng thái nháp.');return;}const [id,v]=form()['selected-template'].split('@'),t=s.templates.find(t=>t.id===id&&t.version===+v);if(!t){error('Chưa có mẫu đã duyệt.');return;}const i=itemTemplate(t,p.items.length);i.id='CT'+Date.now().toString().slice(-7);i.origin=s.role==='admin'?'Cấp quản lý giao':'Đơn vị đăng ký';itemEditor(i);},
 'item-edit':el=>itemEditor(effectivePlan().items.find(i=>i.id===el.dataset.id)),
 'item-save':()=>{if(!guard('unit','admin'))return;const p=effectivePlan(),f=form(),t=B.templateFor(s,editItem);if(!['draft','returned'].includes(p.status)){error('Chỉ sửa nháp; tạo điều chỉnh nếu đã duyệt.');return;}const i={...editItem,name:f.iname,target:f.itarget,upper:f.iupper??null,due:f.idue,requirement:f.irequirement};if(!i.name.trim()||!i.due||!i.requirement.trim()||t.measure!=='level'&&(i.target===null||i.target<0)||t.scoring==='completion'&&!(i.target>0)||t.compare==='between'&&(i.upper===null||i.upper<i.target)){error('Kiểm tra tên, mục tiêu, cận trên, hạn và mô tả.');return;}const n=p.items.findIndex(x=>x.id===i.id);if(n<0)p.items.push(i);else p.items[n]=i;save('Lưu chỉ tiêu '+i.name);closeModal(true);render();},
 'new-proposal':()=>{if(!guard('unit'))return;modal('Đề xuất chỉ tiêu chưa có mẫu',field('Tên chỉ tiêu cần theo dõi','proposal-name','')+textfield('Mô tả cách đo / nguồn / yêu cầu','proposal-description','')+'<p>Chỉ tiêu mới chuyển người cấu hình hoàn thiện mẫu. Chưa được duyệt vào kế hoạch khi thiếu cách đo/chấm.</p>',btn('Gửi đề xuất','proposal-save','','primary'));},
 'proposal-save':()=>{const f=form();if(!f['proposal-name'].trim()||!f['proposal-description'].trim()){error('Nhập tên và mô tả.');return;}s.proposals=s.proposals||[];s.proposals.push({name:f['proposal-name'],description:f['proposal-description'],status:'configuring'});save('Đề xuất chờ cấu hình: '+f['proposal-name']);closeModal(true);render();toast('Đã lưu đề xuất chờ cấu hình. Người cấu hình tạo mẫu ở bước 1 rồi đơn vị thêm vào kế hoạch.');},
 'allocation':()=>{if(!guard('admin'))return;const p=effectivePlan();modal('Phân bổ điểm cho chỉ tiêu',`<p>Tổng điểm từng tiêu chí phải bằng khung. Ví dụ tiêu chí 10 điểm chia 6 + 4.</p><div id="allocation-form">${p.items.map(i=>field(i.criterion+' · '+esc(i.name)+' (điểm)','alloc-'+i.id,i.cap,'number')).join('')}</div>`,btn('Chia đều theo tiêu chí','divide')+btn('Lưu phân bổ','allocation-save','','primary'));},
 'divide':()=>{const p=effectivePlan();for(const i of p.items){const a=p.items.filter(x=>x.criterion===i.criterion);$('#alloc-'+i.id).value=s.criteria.find(c=>c.code===i.criterion).cap/a.length;}dialogDirty=true;},
 'allocation-save':()=>{const p=effectivePlan();if(!['draft','returned'].includes(p.status)){error('Chỉ sửa phân bổ trong bản nháp.');return;}const f=form(),candidate=structuredClone(p);candidate.items.forEach(i=>i.cap=f['alloc-'+i.id]);const e=B.planErrors(s,candidate);if(e.length){error(e);return;}p.items=candidate.items;save('Lưu phân bổ điểm');closeModal(true);render();},
 'plan-submit':()=>{if(!guard('unit','admin'))return;const p=effectivePlan();if(!['draft','returned'].includes(p.status)){toast('Kế hoạch không ở trạng thái nháp.');return;}const e=B.planErrors(s,p);if(s.config.status!=='approved')e.push('Cấu hình kỳ đánh giá chưa duyệt.');if(e.length){toast(e.join(' '));return;}p.status='pending';save('Trình kế hoạch v'+p.version);render();},
 'plan-approve':()=>{if(!guard('admin'))return;const p=effectivePlan();if(p.status!=='pending'){toast('Cần trình kế hoạch trước khi duyệt.');return;}const e=B.planErrors(s,p);if(e.length){toast(e.join(' '));return;}p.status='approved';p.approvedBy=roles[s.role];p.approvedAt=new Date().toLocaleString('vi-VN');if(s.plan.adjustment){s.planHistory=s.planHistory||[];const old=structuredClone(s.plan);delete old.adjustment;s.planHistory.push({plan:old,reports:structuredClone(s.reports),assessment:structuredClone(s.assessment),at:new Date().toLocaleString('vi-VN')});s.plan=p;s.reports={};s.assessment={...B.seed().assessment};toast('Đã duyệt điều chỉnh. Báo cáo phải xác nhận lại theo bản mới; bản cũ được giữ trong lịch sử.');}save('Duyệt kế hoạch v'+p.version);render();},
 'plan-return':()=>{if(!guard('admin'))return;const p=effectivePlan();if(p.status!=='pending'){toast('Chỉ trả kế hoạch đang chờ duyệt.');return;}const why=prompt('Lý do trả kế hoạch:');if(!why?.trim())return;p.status='returned';save('Trả kế hoạch: '+why);render();},
 'adjust-plan':()=>{if(!guard('unit','admin'))return;if(s.assessment.status!=='draft'){toast('Hồ sơ đã chuyển xử lý. Cần được trả về trước khi điều chỉnh kế hoạch.');return;}const why=prompt('Lý do và căn cứ điều chỉnh (bắt buộc):');if(!why?.trim())return;s.plan.adjustment={...structuredClone(s.plan),status:'draft',version:s.plan.version+1,reason:why};save('Tạo đề nghị điều chỉnh: '+why);render();},
 'cancel-adjust':()=>{if(!guard('unit','admin'))return;if(s.plan.adjustment?.status==='pending'){toast('Bản đang chờ duyệt cần được trả trước.');return;}delete s.plan.adjustment;save('Hủy bản điều chỉnh nháp');render();},
 'fill-reports':()=>{if(!guard('unit'))return;if(s.plan.status!=='approved'||s.assessment.status!=='draft'){toast('Cần kế hoạch đã duyệt và hồ sơ tự đánh giá còn nháp.');return;}if(Object.keys(s.reports).length&&!confirm('Thay các bản nháp bằng số liệu ví dụ? Bản chính thức được giữ.'))return;const previous=structuredClone(s.reports);sampleReports();for(const id of Object.keys(previous)){if(!s.reports[id])continue;if(previous[id].official)s.reports[id].official=previous[id].official;s.reports[id].history=previous[id].history||[];}save('Điền 11 báo cáo mẫu nháp');render();},
 'report-edit':el=>reportEditor(s.plan.items.find(i=>i.id===el.dataset.id)), 'report-save':()=>saveReport(false),'report-send':()=>saveReport(true),
 'send-all':()=>{if(!guard('unit'))return;if(s.plan.status!=='approved'||s.assessment.status!=='draft'){toast('Hồ sơ không cho phép cập nhật.');return;}let count=0;for(const i of s.plan.items){const r=s.reports[i.id]?.draft;if(!r||!['draft','returned'].includes(r.status))continue;const e=B.reportErrors(B.templateFor(s,i),r);if(e.length){toast(i.name+': '+e.join(' '));return;}}for(const box of Object.values(s.reports)){if(box.draft&&['draft','returned'].includes(box.draft.status)){box.draft.status='waiting';count++;}}save('Gửi '+count+' báo cáo xác nhận');render();toast('Đã gửi '+count+' báo cáo. Chuyển vai trò Người xác nhận số liệu.');},
 'confirm-all':()=>{if(!guard('verifier'))return;if(s.assessment.status!=='draft'){toast('Hồ sơ đang xử lý; báo cáo nguồn không đổi bản đã trình.');return;}let count=0;for(const id of Object.keys(s.reports))if(confirmReport(id))count++;save('Xác nhận '+count+' báo cáo');render();toast('Đã xác nhận '+count+' báo cáo.');},
 'report-confirm':el=>{if(!guard('verifier'))return;if(s.assessment.status!=='draft')return;if(confirmReport(el.dataset.id)){save('Xác nhận báo cáo '+el.dataset.id);render();}},
 'report-return':el=>{if(!guard('verifier'))return;const why=prompt('Lý do cần bổ sung:');if(!why?.trim())return;s.reports[el.dataset.id].draft.status='returned';s.reports[el.dataset.id].draft.returnReason=why;save('Trả báo cáo '+el.dataset.id+': '+why);render();},
 'report-history':el=>{const box=s.reports[el.dataset.id]||{};modal('Lịch sử báo cáo',table(['Bản','Kết quả / minh chứng','Người xác nhận'],[...(box.history||[]),...(box.official?[box.official]:[]),...(box.draft?[box.draft]:[])].map((r,i)=>['Bản '+(i+1)+' · '+(status[r.status]||r.status),esc(r.value??r.level??(r.numerator+'/'+r.total))+'<small>'+esc(r.evidence)+'</small>',esc(r.confirmedBy||'Chưa xác nhận')])));},
 'save-notes':()=>{if(!guard('unit'))return;if(s.assessment.status!=='draft'){toast('Chỉ sửa nhận xét khi hồ sơ ở nháp.');return;}notesFromPage();save('Lưu nhận xét và đề xuất');toast('Đã lưu nhận xét.');},
 'conditions-tab':()=>{notesFromPage();tab='conditions';render();},
 'to-head':()=>{if(!guard('unit'))return;if(s.assessment.status!=='draft'){toast('Hồ sơ đã chuyển người xử lý.');return;}notesFromPage();const {c,rs}=aggregateReports(),e=B.planErrors(s);for(const i of s.plan.items){if(rs[i.id])e.push(...B.reportErrors(B.templateFor(s,i),rs[i.id]).map(x=>i.name+': '+x));}if(s.plan.status!=='approved')e.push('Kế hoạch chưa duyệt.');if(!c.complete)e.push('Thiếu kết quả xác nhận: '+c.missing.join(', '));if(!s.assessment.strength.trim()||!s.assessment.weakness.trim())e.push('Thiếu ưu điểm hoặc hạn chế.');if(e.length){toast(e.join(' '));return;}s.assessment.status='head';save('Chuyển người đứng đầu xác nhận');render();toast('Chuyển vai trò Người đứng đầu để xác nhận và trình.');},
 'submit-assessment':()=>{if(!guard('head'))return;if(s.assessment.status!=='head'){toast('Người lập phải chuyển hồ sơ trước.');return;}const {c}=aggregateReports();if(!c.complete||B.planErrors(s).length){toast('Thiếu dữ liệu hoặc phân bổ, không thể trình.');return;}s.assessment.snapshot=snapshot();s.assessment.status='submitted';save('Người đứng đầu xác nhận và trình; lưu cố định hồ sơ');render();},
 'head-return':()=>{if(!guard('head'))return;if(s.assessment.status!=='head'){toast('Chỉ trả hồ sơ đang chờ người đứng đầu.');return;}const why=prompt('Lý do trả về người lập:');if(!why?.trim())return;s.assessment.status='draft';save('Người đứng đầu trả bổ sung: '+why);render();},
 'criterion-detail':el=>{const snap=s.assessment.snapshot,ss=snap?{...s,plan:snap.plan,templates:snap.templates}:s,rs=snap?.reports||officials();modal('Căn cứ tiêu chí '+el.dataset.id,table(['Chỉ tiêu','Mục tiêu / số thực tế','Cách tính / điểm','Minh chứng / xác nhận'],ss.plan.items.filter(i=>i.criterion===el.dataset.id).map(i=>{const t=B.templateFor(ss,i),r=rs[i.id];return [esc(i.name),esc(i.target)+' / '+esc(B.value(t,r)),scoreName(t.scoring)+'<small>'+fmt(B.score(t,i,r))+' / '+fmt(i.cap)+'</small>',esc(r?.evidence||'Thiếu')+'<small>'+esc(r?.confirmedBy||'Chưa xác nhận')+'</small>'];})));},
 'condition-record':()=>{if(s.assessment.status!=='draft'){toast('Hồ sơ đã chuyển xử lý; không bổ sung trực tiếp bản đã trình.');return;}modal('Hồ sơ căn cứ điều kiện',select('Loại hồ sơ (để kiểm tra điều kiện)','record-type',{remedy:'Khắc phục hạn chế',verification:'Xác minh phản ánh',exception:'Trường hợp đặc biệt',conclusion:'Kết luận đã xác minh'},'remedy')+textfield('Nội dung và kết quả xử lý','record-text','')+field('Văn bản / mã hồ sơ / tài liệu kiểm chứng','record-evidence','')+check('Đã được người có quyền xác nhận','record-confirmed',false)+'<p>Demo lưu hồ sơ căn cứ, không tự đổi các điều kiện đã xác minh. Bản triển khai cần phân công người xác nhận theo loại hồ sơ.</p>',btn('Lưu hồ sơ căn cứ','record-save','','primary'));},
 'record-save':()=>{if(!guard('unit','verifier','reviewer','admin'))return;const f=form();if(!f['record-text'].trim()||!f['record-evidence'].trim()){error('Nhập nội dung và tài liệu.');return;}if(f['record-confirmed']&&!allowed('verifier','reviewer')){error('Người lập chỉ gửi hồ sơ, không tự xác nhận.');return;}s.records=s.records||[];s.records.push({...f,year:s.year,org:s.org,by:roles[s.role]});save('Bổ sung hồ sơ căn cứ '+f['record-type']);closeModal(true);render();},
 'init-review':()=>{if(!guard('reviewer'))return;if(s.assessment.status!=='submitted'){toast('Chỉ khởi tạo thẩm định khi hồ sơ đã trình.');return;}if(Object.keys(s.review.reports).length&&!confirm('Khởi tạo lại bản thẩm định từ bản đã trình?'))return;s.review.reports=structuredClone(s.assessment.snapshot.reports);save('Khởi tạo thẩm định riêng');render();},
 'review-criterion':el=>{if(!s.assessment.snapshot){toast('Chưa có bản đã trình.');return;}const a=s.assessment.snapshot.plan.items.filter(i=>i.criterion===el.dataset.id);modal('Các chỉ tiêu cần đối chiếu',table(['Chỉ tiêu','Thao tác'],a.map(i=>[esc(i.name),btn('Mở số liệu thẩm định','review-item',`data-id="${i.id}"`)])));},
 'review-item':el=>reportEditor(s.assessment.snapshot.plan.items.find(i=>i.id===el.dataset.id),true),
 'review-item-save':()=>{if(!guard('reviewer'))return;if(s.assessment.status!=='submitted'){error('Hồ sơ không ở bước thẩm định.');return;}const r=readReport(),t=B.templateFor(s,reviewItem),e=B.reportErrors(t,r),old=s.assessment.snapshot.reports[reviewItem.id],reason=form().rreason;const keys=['value','numerator','total','level','quality'];if(keys.some(k=>r[k]!==old[k])&&!reason.trim())e.push('Số liệu khác bản tự đánh giá cần lý do điều chỉnh.');if(e.length){error(e);return;}s.review.reports[reviewItem.id]={...r,status:'confirmed',confirmedBy:roles[s.role],confirmedAt:new Date().toLocaleString('vi-VN')};s.review.reasons[reviewItem.id]=reason;save('Lưu số liệu thẩm định riêng '+reviewItem.id);closeModal(true);render();},
 'save-review':()=>{if(!guard('reviewer'))return;if(s.assessment.status!=='submitted'){toast('Hồ sơ không ở bước thẩm định.');return;}reviewFromPage();save('Lưu ý kiến thẩm định');toast('Đã lưu; chưa hoàn tất thẩm định.');},
 'finish-review':()=>{if(!guard('reviewer'))return;if(s.assessment.status!=='submitted'){toast('Chỉ hoàn tất hồ sơ đang thẩm định.');return;}reviewFromPage();if(!s.review.opinion.trim()||!Object.keys(s.review.reports).length){toast('Khởi tạo bản thẩm định và ghi ý kiến trước khi hoàn tất.');return;}s.review.status='reviewed';s.assessment.status='reviewed';save('Hoàn tất thẩm định');render();},
 'return-assessment':()=>{if(!guard('reviewer'))return;if(s.assessment.status!=='submitted'){toast('Chỉ trả hồ sơ đang thẩm định.');return;}const why=prompt('Yêu cầu bổ sung (bắt buộc):');if(!why?.trim())return;s.assessment.history=s.assessment.history||[];s.assessment.history.push({snapshot:structuredClone(s.assessment.snapshot),review:structuredClone(s.review),reason:why});s.assessment.snapshot=null;s.assessment.status='draft';s.review=structuredClone(B.seed().review);save('Trả hồ sơ bổ sung: '+why);render();},
 'recognize':()=>{if(!guard('approver'))return;if(s.assessment.status!=='reviewed'){toast('Cần hoàn tất thẩm định trước khi công nhận.');return;}modal('Quyết định công nhận',optsRating('decision-rating',s.review.proposed)+field('Số quyết định (người công nhận nhập)','decision-number','')+field('Ngày quyết định (ngày văn bản)','decision-date','2026-12-10','date')+select('Người ký (chọn nhân sự đúng quyền)','decision-signer',{'Người công nhận mẫu':'Người công nhận mẫu'},'Người công nhận mẫu','Bản thật lấy danh sách nhân sự được phép ký trong phạm vi cấp công nhận.')+field('Căn cứ quyết định (tên/số văn bản)','decision-basis','')+field('Tệp quyết định (tên / mã tài liệu demo)','decision-file','')+textfield('Lý do xem xét riêng (bắt buộc nếu điều kiện chưa phù hợp)','decision-exception','')+`<div class="notice" id="decision-check"></div>`,btn('Kiểm tra điều kiện','decision-check')+btn('Công nhận và khóa hồ sơ','decision-save','','primary'));checkDecision();},
 'decision-check':()=>checkDecision(),
 'decision-save':()=>{if(!guard('approver'))return;if(s.assessment.status!=='reviewed'){error('Hồ sơ phải được thẩm định trước khi công nhận.');return;}const f=form(),snap=s.assessment.snapshot,ss={...s,plan:snap.plan,templates:snap.templates,criteria:snap.criteria},total=B.totals(ss,{...snap.reports,...s.review.reports}),chosen=f['decision-rating'],q=B.quota(s),conditions=B.eligibility({...s,tasks:snap.tasks,conditions:snap.conditions},chosen,total.total);if(!f['decision-number'].trim()||!f['decision-date']||!f['decision-signer'].trim()||!f['decision-basis'].trim()||!f['decision-file'].trim()){error('Thiếu số/ngày quyết định, người ký, căn cứ hoặc tài liệu.');return;}if(!total.complete){error('Chưa đủ số liệu thẩm định.');return;}if(chosen==='excellent'&&q.excellent>=q.max){error('Vượt hạn mức xuất sắc. Không thể công nhận trong demo.');return;}if(conditions.some(x=>x.ok!==true)&&!f['decision-exception'].trim()){error('Điều kiện chưa phù hợp; người có quyền phải ghi lý do và căn cứ xem xét riêng. Không tự đổi điểm hoặc hạ mức.');return;}s.decision={rating:chosen,points:total.total,number:f['decision-number'],date:f['decision-date'],signer:f['decision-signer'],basis:f['decision-basis'],file:f['decision-file'],exception:f['decision-exception'],at:new Date().toLocaleString('vi-VN')};s.assessment.status='recognized';save('Công nhận '+rating[chosen]+' và khóa hồ sơ');closeModal(true);render();},
 'notify':()=>{if(!guard('approver'))return;if(!s.decision){toast('Chưa có quyết định công nhận.');return;}modal('Thông báo kết quả',field('Nơi nhận (đơn vị / cơ quan)','recipient',s.org)+textfield('Nội dung thông báo','notification','Kết quả '+s.year+': '+rating[s.decision.rating]+'. Quyết định '+s.decision.number)+ '<p>Demo ghi lịch sử thông báo trên trình duyệt, không gửi tin nhắn ra ngoài.</p>',btn('Ghi nhận đã thông báo','notify-save','','primary'));},
 'notify-save':()=>{const f=form();if(!f.recipient.trim()||!f.notification.trim()){error('Nhập nơi nhận và nội dung.');return;}s.notified={recipient:f.recipient,text:f.notification,at:new Date().toLocaleString('vi-VN')};save('Thông báo kết quả tới '+f.recipient);closeModal(true);render();},
 'print-info':()=>{const p=s.printInfo||{};modal('Thông tin bổ sung để in',field('Địa danh (người lập nhập)','print-place',p.place||'')+field('Ngày lập phiếu (người lập nhập)','print-date',p.date||'2026-10-13','date')+field('Người đứng đầu (bản thật lấy hồ sơ nhân sự)','print-head',p.head||'')+field('Chức vụ người đứng đầu','print-position',p.position||'')+'<p>Điểm, mức và quyết định lấy hồ sơ; không sửa bằng biểu mẫu in. Chữ ký trong demo để trống, không thay ký số.</p>',btn('Lưu thông tin in','print-save','','primary'));},
 'print-save':()=>{if(!guard('unit','head'))return;if(s.assessment.status!=='draft'){error('Thông tin in thuộc hồ sơ đã chuyển xử lý. Cần được trả về để sửa trước khi trình lại.');return;}const f=form();s.printInfo={place:f['print-place'],date:f['print-date'],head:f['print-head'],position:f['print-position']};save('Lưu thông tin phiếu in');closeModal(true);render();},
 'print-preview':()=>{const p=s.printInfo;if(!p?.place||!p?.date||!p?.head||!p?.position){toast('Bổ sung địa danh, ngày, người đứng đầu và chức vụ ở Thông tin phiếu in.');return;}showPrint();},
 'print-now':()=>window.print(),
 'export-plan':()=>exportCsv('chi-tieu',s.plan.items.map(i=>[i.id,i.name,i.criterion,i.target,i.upper,i.due,i.cap,s.plan.status,s.plan.version]),['Mã','Tên','Tiêu chí','Mục tiêu','Cận trên','Hạn','Điểm tối đa','Trạng thái','Phiên bản']),
 'export-reports':()=>exportReportCsv(), 'export-results':()=>exportReportCsv(),
 'import':()=>importDialog(), 'import-check':()=>validateImport(), 'import-apply':()=>applyImport(),
 'tour-template':()=>startTour('template'), 'tour-report':()=>startTour('report')
};
function checkDecision(){const f=form(),snap=s.assessment.snapshot,ss={...s,plan:snap.plan,templates:snap.templates,criteria:snap.criteria},total=B.totals(ss,{...snap.reports,...s.review.reports}),rows=B.eligibility({...s,tasks:snap.tasks,conditions:snap.conditions},f['decision-rating'],total.total),q=B.quota(s);$('#decision-check').innerHTML=`Điểm thẩm định: ${fmt(total.total)}. ${rows.map(x=>`${x.ok?'✓':'!'} ${esc(x.name)}`).join('<br>')}<br>Hạn mức xuất sắc: ${q.excellent}/${q.max}. Nếu chưa phù hợp cần xem xét có căn cứ, không tự đổi điểm.`;}
function showPrint(){const snap=s.assessment.snapshot,ss=snap?{...s,plan:snap.plan,criteria:snap.criteria,templates:snap.templates}:s,rs=snap?.reports||officials(),self=B.totals(ss,rs),review=s.review.status==='reviewed'?B.totals(ss,{...rs,...s.review.reports}):null,p=snap?.printInfo||s.printInfo,d=s.decision;$('#main').innerHTML=`<div class="actions noprint">${btn('← Quay lại kết quả','print-back')}${btn('In / Lưu PDF','print-now','','primary')}</div><div class="printtitle"><p>NOTE WORK · ${esc(s.org)}</p><h1>Phiếu đánh giá tổ chức năm ${s.year}</h1><p>${d?'Bản đã công nhận':'Bản đang xử lý · '+esc(status[s.assessment.status])}</p></div><p>Người đứng đầu: ${esc(p.head)} · ${esc(p.position)}</p><div class="card">${table(['STT','Nội dung tiêu chí','Điểm tối đa','Đơn vị tự chấm','Thẩm định','Tài liệu kiểm chứng'],ss.criteria.map((c,i)=>[i+1,c.code+' · '+c.title,fmt(c.cap),fmt(self.by[c.code]),review?fmt(review.by[c.code]):'',ss.plan.items.filter(x=>x.criterion===c.code).map(x=>esc(rs[x.id]?.evidence||'')).join('<br>')]).concat([['','Tổng A',30,fmt(Object.entries(self.by).filter(([k])=>k[0]==='A').reduce((n,[,v])=>n+(v||0),0)),review?fmt(Object.entries(review.by).filter(([k])=>k[0]==='A').reduce((n,[,v])=>n+(v||0),0)):'',''],['','Tổng B',70,fmt(Object.entries(self.by).filter(([k])=>k[0]==='B').reduce((n,[,v])=>n+(v||0),0)),review?fmt(Object.entries(review.by).filter(([k])=>k[0]==='B').reduce((n,[,v])=>n+(v||0),0)):'',''],['','Tổng cộng',100,fmt(self.total),review?fmt(review.total):'','']]))}</div><p><b>Ưu điểm:</b> ${esc(s.assessment.strength)}</p><p><b>Hạn chế:</b> ${esc(s.assessment.weakness)}</p><p><b>Đề xuất:</b> ${rating[s.assessment.proposed]}</p><p><b>Điều kiện:</b> ${B.eligibility(s,s.assessment.proposed,self.total).map(x=>`${esc(x.name)}: ${x.ok?'Đáp ứng':'Cần xem xét'}`).join('; ')}.</p><p><b>Ý kiến thẩm định:</b> ${esc(s.review.opinion)}</p><p><b>Quyết định:</b> ${d?esc(d.number)+' · '+date(d.date)+' · '+rating[d.rating]:''}</p><p class="right">${esc(p.place)}, ngày ${date(p.date)}</p><div class="grid"><div><p>Người đứng đầu đơn vị</p><p style="height:70px"></p>${esc(p.head)}</div><div><p>Người công nhận</p><p style="height:70px"></p>${d?esc(d.signer):''}</div></div>`;handlers['print-back']=()=>render();}
function exportCsv(name,rows,heads){const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const text='\ufeff'+[heads,...rows].map(r=>r.map(cell).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name+'-'+s.year+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất toàn bộ dữ liệu theo bộ lọc, mở được bằng Excel.');}
function exportReportCsv(){const snap=s.assessment.snapshot,ss=snap?{...s,plan:snap.plan,templates:snap.templates}:s,rs=snap?.reports||officials(),query=($('#search')?.value||'').toLowerCase();exportCsv('ket-qua',ss.plan.items.filter(i=>i.name.toLowerCase().includes(query)).map(i=>{const t=B.templateFor(ss,i),r=rs[i.id];return [s.org,s.year,i.id,i.name,i.criterion,i.target,B.value(t,r),B.score(t,i,r),s.review.status==='reviewed'?B.score(t,i,s.review.reports[i.id]||r):null,r?.date,r?.evidence,r?.status||'Chưa báo cáo',s.decision?rating[s.decision.rating]:'Chưa công nhận',ss.plan.version,i.templateVersion];}),['Đơn vị','Năm','Mã','Tên chỉ tiêu','Tiêu chí','Mục tiêu','Kết quả','Điểm tự chấm','Điểm thẩm định','Ngày số liệu','Minh chứng','Trạng thái','Kết quả chính thức','Phiên bản kế hoạch','Phiên bản mẫu']);}
let stagedImport=[];
function importDialog(){modal('Nhập chỉ tiêu từ bảng CSV',`<p>Lưu Excel thành <b>CSV UTF-8</b>, dùng mẫu sau. Demo kiểm từng dòng trước khi nhập; chưa hỗ trợ đọc trực tiếp .xlsx.</p>${btn('Tải mẫu CSV','import-sample')}<pre style="white-space:pre-wrap">mau_id,muc_tieu,can_tren,han,mo_ta\nMA1,500,,2026-12-14,Kết quả cả năm</pre>${field('Chọn CSV UTF-8 (ngăn cách dấu phẩy)','import-file','','file','', 'accept=".csv,text/csv"')}<div id="import-result"></div>`,btn('Kiểm tra từng dòng','import-check')+btn('Áp dụng các dòng hợp lệ','import-apply','','primary'));stagedImport=[];handlers['import-sample']=()=>exportCsv('mau-nhap-chi-tieu',s.templates.filter(t=>t.status==='approved').map(t=>[t.id,t.target,t.upper,s.config.deadline,t.definition]),['mau_id','muc_tieu','can_tren','han','mo_ta']);}
function parseCsv(text){let rows=[],r=[],v='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){v+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){r.push(v);v='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;r.push(v);if(r.some(x=>x.trim()))rows.push(r);r=[];v='';}else v+=c;}if(quoted)throw Error('Dấu nháy kép chưa đóng.');if(v||r.length){r.push(v);rows.push(r);}return rows;}
async function validateImport(){const file=$('#import-file').files[0];if(!file){error('Chọn file CSV trước.');return;}let rows;try{rows=parseCsv((await file.text()).replace(/^\ufeff/,''));}catch(e){error(e.message);return;}if(rows[0]?.join(',')!=='mau_id,muc_tieu,can_tren,han,mo_ta'){error('Tên cột phải đúng mẫu CSV.');return;}stagedImport=[];let errs=0;const preview=rows.slice(1).map((r,n)=>{const t=s.templates.filter(x=>x.id===r[0]&&x.status==='approved').sort((a,b)=>b.version-a.version)[0];const error=[];if(r.length!==5)error.push('Phải đủ 5 cột');if(!t)error.push('Mẫu không tồn tại/chưa duyệt');if(!r[3]?.match(/^\d{4}-\d{2}-\d{2}$/)||Number.isNaN(Date.parse(r[3]))||new Date(r[3]).toISOString().slice(0,10)!==r[3]||+r[3].slice(0,4)!==s.year)error.push('Ngày thật theo yyyy-mm-dd, thuộc năm đánh giá');if(!r[4]?.trim())error.push('Thiếu mô tả');if(t&&t.measure!=='level'&&(r[1]===''||!Number.isFinite(+r[1])||+r[1]<0))error.push('Mục tiêu phải là số không âm');if(t?.measure==='level'&&!t.levels.some(x=>x.name===r[1]))error.push('Mức mục tiêu chưa có trong mẫu');if(t?.scoring==='completion'&&!(+r[1]>0))error.push('Mục tiêu phải > 0');if(t?.compare==='between'&&(r[2]===''||!Number.isFinite(+r[2])||+r[2]<+r[1]))error.push('Cận trên không hợp lệ');if(error.length)errs++;else {const i=itemTemplate(t,n);Object.assign(i,{id:'CSV'+Date.now()+n,target:t.measure==='level'?r[1]:+r[1],upper:r[2]===''?null:+r[2],due:r[3],originalDue:r[3],requirement:r[4],cap:0,origin:'Nhập CSV'});stagedImport.push(i);}return [n+2,esc(r[0]),error.length?`<span class="badge bad">${esc(error.join('; '))}</span>`:'<span class="badge ok">Hợp lệ</span>'];});$('#import-result').innerHTML=table(['Dòng trong file','Mẫu','Kết quả kiểm tra'],preview)+`<p>${stagedImport.length} dòng hợp lệ, ${errs} dòng lỗi. Chỉ dòng hợp lệ được nhập; phải phân bổ điểm trước khi trình.</p>`;}
function applyImport(){if(!guard('unit','admin'))return;const p=effectivePlan();if(!['draft','returned'].includes(p.status)){error('Chỉ nhập vào kế hoạch nháp.');return;}if(!stagedImport.length){error('Kiểm tra file và có dòng hợp lệ trước.');return;}p.items.push(...stagedImport);save('Nhập '+stagedImport.length+' chỉ tiêu CSV đã kiểm lỗi');closeModal(true);render();}
const tours={
 'index':[['.stepgrid','Một luồng gồm sáu bước','Các trang đi từ cấu hình đến quyết định cuối. Bấm từng ô để mở trang.'],['#scenario','Trình diễn nhanh','Nạp bộ số liệu đã xác nhận để thử từ bước tự đánh giá.'],['#role','Chuyển vai trò','Mỗi thao tác thuộc một vai trò. Đây là bộ chọn để thử quy trình, không phải đăng nhập thật.']],
 'cau-hinh':[['#period','1. Chọn kỳ đánh giá','Năm, hạn chốt và ngày áp dụng xác định hồ sơ dùng bộ quy tắc nào.'],['#period-button','2. Cấu hình thời gian','Người cấu hình nhập căn cứ và hạn chốt. Bản đã dùng không được đổi ngầm.'],['#templates','3. Đọc các mẫu','Mẫu cho biết cách đo, chấm và nguồn số liệu. Đơn vị chỉ dùng mẫu đã duyệt.'],['#template-add','4. Tạo mẫu mới','Mở biểu mẫu; có hướng dẫn riêng về mức %, cận dưới và cận trên. Sau lưu nháp cần trình và duyệt.'],['.nav a[href="chi-tieu.html"]','5. Chuyển sang chỉ tiêu năm','Dùng mẫu đã duyệt để giao hoặc đăng ký mục tiêu cho đơn vị.']],
 'chi-tieu':[['#apply-set','1. Tạo nhanh từ mẫu','Tạo các dòng kế thừa cách đo/chấm. Đây là bản nháp, chưa được báo cáo.'],['#plan-table','2. Nhập mục tiêu và hạn','Mở Chi tiết ở từng dòng để kiểm 8 trường. Hạn và mục tiêu do người lập nhập.'],['.tabs','3. Kiểm phân bổ và căn cứ','Mở Phân bổ điểm: tổng điểm con bằng tiêu chí, A=30, B=70. Nhiệm vụ làm căn cứ xếp loại được đếm riêng.'],['#plan-submit','4. Trình bảng chỉ tiêu','Hệ thống chỉ rõ lỗi thiếu/vượt điểm, mẫu hoặc mục tiêu. Đang chờ duyệt không sửa trực tiếp.'],['#role','5. Duyệt đúng vai trò','Chọn Người cấu hình / duyệt kế hoạch, sau đó bấm Duyệt bảng chỉ tiêu.'],['#plan-approve','6. Duyệt kế hoạch','Duyệt xong mới sang bước báo cáo. Trả kế hoạch cần lý do.']],
 'bao-cao':[['#report-table','1. Chọn chỉ tiêu cần báo cáo','Mục tiêu và điểm tối đa lấy kế hoạch đã duyệt. Bấm Nhập kết quả / Cập nhật ở đúng dòng.'],['#fill-reports','2. Có thể điền ví dụ để thử','Tạo bản nháp có số gốc và tài liệu minh họa cho từng dòng; chưa xác nhận chính thức.'],['#send-all','3. Gửi xác nhận','Kiểm số đạt/tổng số, ngày, chất lượng và minh chứng rồi chuyển người xác nhận.'],['#role','4. Chuyển người xác nhận','Đổi vai trò để đối chiếu báo cáo. Đơn vị không tự xác nhận số liệu của mình.'],['#confirm-all','5. Xác nhận kết quả','Sau xác nhận điểm mới được đưa vào bảng tự đánh giá. Sửa tiếp sẽ tạo bản mới.']],
 'tu-danh-gia':[['#score-total','1. Đọc tổng điểm','Cộng điểm các chỉ tiêu, không cộng lại điểm cha. Thiếu báo cáo thì tổng chưa chốt.'],['.tabs','2. Kiểm điều kiện và minh chứng','Điểm và điều kiện cùng phải đạt. Ví dụ 3/12 nhiệm vụ vượt chỉ là 25%, chưa đủ 30%.'],['#self-notes','3. Viết nhận xét và đề xuất','Người lập ghi ưu điểm, hạn chế và mức đề xuất; không sửa trực tiếp điểm.'],['#to-head','4. Chuyển người đứng đầu','Chỉ chuyển khi kế hoạch và kết quả xác nhận đủ.'],['#role','5. Đổi vai trò','Người đứng đầu kiểm hồ sơ, xác nhận rồi trình.'],['#submit-assessment','6. Lưu bản cố định khi trình','Cố định tiêu chí, kế hoạch, số liệu, điểm và tài liệu. Nguồn thay đổi không tự sửa bản trình.']],
 'tham-dinh':[['#init-review','1. Khởi tạo bản thẩm định','Sao chép bản đã trình sang bộ số liệu thẩm định riêng.'],['#review-table','2. Đối chiếu từng chỉ tiêu','Bấm Thẩm định chỉ tiêu. Nhập số liệu kiểm chứng, không nhập tùy ý tổng điểm.'],['#finish-review','3. Hoàn tất thẩm định','Lưu ý kiến và mức đề xuất, chuyển người có quyền quyết định.'],['#quota','4. Kiểm hạn mức','Lấy tất cả kết quả cùng năm/cấp. Tối đa = phần nguyên của 20% × số hoàn thành tốt; không gồm xuất sắc.'],['#recognize','5. Công nhận','Vai trò Người công nhận nhập số/ngày quyết định, người ký, căn cứ và tài liệu.'],['#notify','6. Thông báo','Sau công nhận, chọn nơi nhận và ghi lịch sử thông báo.']],
 'ket-qua':[['#result-summary','1. Phân biệt kết quả chính thức','Chỉ bản đã công nhận có mức cuối và quyết định.'],['#export-results','2. Xuất toàn bộ bảng đang lọc','CSV mở được bằng Excel, kèm phiên bản, ngày số liệu và trạng thái.'],['#print-info','3. Bổ sung thông tin in','Nhập địa danh, ngày lập, người đứng đầu và chức vụ trước khi khóa hồ sơ. Điểm và quyết định lấy từ hồ sơ.'],['#print-preview','4. Xem trước rồi in','Phiếu có đủ 11 tiêu chí và 6 cột. Bước chưa xử lý để trống; không tự điền chữ ký.']],
 'template':[['#tmeasure','1. Cách đo','Giá trị trực tiếp: nhập số. Tỷ lệ: nhập số đạt/tổng số. Mức: chọn mô tả đã duyệt.'],['#tscoring','2. Cách chấm','Mức hoàn thành chỉ dùng khi càng cao càng tốt. Mục tiêu giảm, bằng hoặc khoảng dùng bảng khoảng.'],['#tcompare','3. Mục tiêu đạt thế nào','Ít nhất, không quá, bằng, trong khoảng hay đạt mức. Đây là kiểm đạt mục tiêu, khác với tính điểm.'],['#score-fields','4. Tỷ lệ điểm và khoảng','Tỷ lệ điểm = % của điểm tối đa. Cận dưới/trên = giá trị kết quả; kiểm điểm biên để không hở hoặc trùng.'],['#trial-button','5. Thử tính','Nhập kết quả và điểm tối đa để kiểm quy tắc trước khi duyệt.'],['#template-save','6. Lưu nháp rồi trình','Mẫu nháp chưa được áp dụng. Phiên bản đã dùng được giữ nguyên.']],
 'report':[['#score-preview','1. Điểm là kết quả tính','Nhập số gốc ở phía trên; điểm và trạng thái đạt mục tiêu tự tính.'],['#revidence','2. Gắn tài liệu','Tài liệu thuộc đúng lần báo cáo, giúp người xác nhận kiểm số và phạm vi.'],['#rdate','3. Ghi ngày số liệu','Khác ngày hoàn thành thực tế. Không lấy ngày nhập thay ngày hoàn thành.'],['#report-send','4. Gửi xác nhận','Báo cáo nháp chỉ xem trước. Thiếu số hoặc tài liệu sẽ chặn gửi.']]
};
function startTour(key=page){stopTour();tourSteps=(tours[key]||[]).filter(x=>$(x[0]));tourIndex=0;showTour();}
function stopTour(){document.querySelectorAll('.tour-ring,.tourbox').forEach(x=>x.remove());tourSteps=[];}
function showTour(reposition=false){document.querySelectorAll('.tour-ring,.tourbox').forEach(x=>x.remove());const step=tourSteps[tourIndex];if(!step)return;const target=$(step[0]);if(!target){tourIndex++;showTour();return;}if(!reposition)target.scrollIntoView({block:'center',behavior:'instant'});const r=target.getBoundingClientRect(),ring=document.createElement('div');ring.className='tour-ring'+(target.tagName==='BUTTON'&&r.width<90?' circle':'');Object.assign(ring.style,{top:Math.max(4,r.top-6)+'px',left:Math.max(4,r.left-6)+'px',width:Math.min(r.width+12,innerWidth-8)+'px',height:Math.min(r.height+12,innerHeight-8)+'px'});document.body.append(ring);const box=document.createElement('div');box.className='tourbox';box.innerHTML=`<button class="tourclose" data-action="tour-close" aria-label="Đóng hướng dẫn">×</button><span class="count">BƯỚC ${tourIndex+1} / ${tourSteps.length}</span><h3>${step[1]}</h3><p>${step[2]}</p><div class="tour-progress"><i style="width:${(tourIndex+1)/tourSteps.length*100}%"></i></div><div class="actions">${btn('← Trước','tour-prev',tourIndex===0?'disabled':'')}${btn(tourIndex===tourSteps.length-1?'Hoàn tất':'Tiếp →','tour-next','','primary')}</div>`;document.body.append(box);const height=box.getBoundingClientRect().height,left=Math.max(12,Math.min(r.left,innerWidth-372));let top=r.bottom+15;if(top+height>innerHeight-12)top=Math.max(12,r.top-height-15);Object.assign(box.style,{top:top+'px',left:left+'px'});box.querySelector('button[data-action=tour-next]').focus();}
handlers['tour-close']=stopTour;handlers['tour-prev']=()=>{tourIndex=Math.max(0,tourIndex-1);showTour();};handlers['tour-next']=()=>{if(++tourIndex>=tourSteps.length)stopTour();else showTour();};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){const action=el.dataset.action;try{const result=handlers[action]?.(el);if(result?.catch)result.catch(ex=>toast('Không thể xử lý: '+ex.message));}catch(ex){console.error(ex);toast('Không thể xử lý: '+ex.message);}}});
document.addEventListener('change',e=>{if(e.target.id==='role'){s.role=e.target.value;save();render();}if(['tscoring','tcompare','tmeasure'].includes(e.target.id)){if(e.target.id==='tmeasure'&&e.target.value==='level'){$('#tscoring').value='level';$('#tcompare').value='level';}if(e.target.id==='tmeasure'&&e.target.value==='ratio')$('#taggregate').value='ratio';renderScoreFields();}if(e.target.id==='rfile'&&e.target.files[0]){$('#revidence').value=e.target.files[0].name;previewReport();}if(e.target.id==='decision-rating')checkDecision();});
document.addEventListener('input',e=>{if(e.target.id==='search'){const q=e.target.value.toLowerCase();$('#main').querySelectorAll('tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q));}if(e.target.closest('.dialog')&&editReport)previewReport();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('.tourbox'))stopTour();else closeModal();}if(e.key==='Tab'&&$('.dialogback')){const all=[...$('.dialogback').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled&&x.getClientRects().length),first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
window.addEventListener('resize',()=>{if(tourSteps.length)showTour();});window.addEventListener('scroll',()=>{if($('.tour-ring')&&tourSteps.length){const st=tourSteps;document.querySelectorAll('.tour-ring,.tourbox').forEach(x=>x.remove());tourSteps=st;showTour(true);}},{passive:true});
render();
})();
